// ---------------------------------------------------------------------
// Favoritos / atalhos pessoais: cada técnico marca os equipamentos que
// mais usa no dia a dia, para não precisar navegar pelas categorias
// toda vez. Guardado em localStorage puro (não é dado sensível do
// usuário atendido, então não passa pelo safeStorage cifrado).
// ---------------------------------------------------------------------
const FAVORITES_KEY = 'argo_favorites';

function getFavoriteIds() {
  try {
    const raw = localStorage.getItem(FAVORITES_KEY);
    return raw ? new Set(JSON.parse(raw)) : new Set();
  } catch (e) {
    return new Set();
  }
}

function isFavorite(id) {
  return getFavoriteIds().has(id);
}

function toggleFavorite(id) {
  const set = getFavoriteIds();
  if (set.has(id)) set.delete(id); else set.add(id);
  try {
    localStorage.setItem(FAVORITES_KEY, JSON.stringify([...set]));
  } catch (e) {
    showImageError(id, 'Não foi possível salvar o favorito (armazenamento indisponível).');
  }
  render();
}

// ---------------------------------------------------------------------
// Recentes: a aba "Recentes" mostra as últimas 6 unidades que o técnico
// abriu (tocou no card, ligou, abriu a rota, expandiu o registro técnico,
// gerou a guia etc.), da mais recente para a mais antiga. Substitui a antiga
// aba "Favoritos". Guardado só neste aparelho, como lista de ids públicos
// do diretório (nenhum dado de usuário atendido), em localStorage puro.
// ---------------------------------------------------------------------
const RECENTS_KEY = 'argo_recentes';
const RECENTS_MAX = 6;

function getRecentIds() {
  try {
    const raw = localStorage.getItem(RECENTS_KEY);
    const arr = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(arr)) return [];
    // descarta ids que não existem mais no diretório e limita a 6
    return arr.filter(id => typeof id === 'string' && DATA.some(i => i.id === id)).slice(0, RECENTS_MAX);
  } catch (e) {
    return [];
  }
}

function recordRecent(id) {
  if (!id) return;
  const list = getRecentIds();
  if (list[0] === id) return; // já é o mais recente: nada a fazer
  const next = [id, ...list.filter(x => x !== id)].slice(0, RECENTS_MAX);
  try {
    localStorage.setItem(RECENTS_KEY, JSON.stringify(next));
  } catch (e) { return; }
  // Só atualiza o número do chip. Não chama render(): refazer a lista no meio
  // do clique apagaria o que a pessoa está digitando e, na aba Recentes,
  // reordenaria os cards debaixo do dedo. A ordem nova aparece no próximo render.
  updateChipCounts();
}

// Um único ouvinte no grid (fase de captura, para valer mesmo quando um botão
// do card usa stopPropagation). Cards de unidade carregam data-unit-id.
(function initRecentTracking() {
  function attach() {
    const grid = document.getElementById('grid');
    if (!grid || grid.dataset.recentsBound) return;
    grid.dataset.recentsBound = '1';
    const handler = (e) => {
      const card = e.target && e.target.closest ? e.target.closest('.tech-card[data-unit-id]') : null;
      if (card) recordRecent(card.getAttribute('data-unit-id'));
    };
    grid.addEventListener('click', handler, true);
    grid.addEventListener('focusin', handler, true);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', attach);
  else attach();
})();

// ---------------------------------------------------------------------
// Ordenar por proximidade: usa a geolocalização do navegador (posição
// atual do dispositivo) e compara com a localização de cada equipamento,
// obtida por geocodificação do endereço cadastrado via Nominatim
// (OpenStreetMap, serviço público e gratuito). Os resultados são
// guardados em cache local, então cada endereço só precisa de internet
// para ser localizado uma vez; depois disso a ordenação funciona mesmo
// offline. É uma ordenação aproximada (depende da precisão do endereço
// cadastrado e do serviço de geocodificação), útil para priorizar rotas
// da Equipe Volante e visitas domiciliares.
// ---------------------------------------------------------------------
const GEOCODE_CACHE_KEY = 'argo_geocode_cache_v2';
let proximityState = { active: false, lat: null, lon: null, loading: false };

// Guardado em memória: renderDistanceBadge() chamava isto uma vez POR CARD
// (JSON.parse do cache inteiro, ~400 vezes por render no modo proximidade).
let _geocodeCacheMemo = null;
function getGeocodeCache() {
  if (_geocodeCacheMemo) return _geocodeCacheMemo;
  try {
    _geocodeCacheMemo = JSON.parse(localStorage.getItem(GEOCODE_CACHE_KEY) || '{}') || {};
  } catch (e) {
    _geocodeCacheMemo = {};
  }
  return _geocodeCacheMemo;
}

function setGeocodeCacheEntry(id, lat, lon, approx, manual) {
  const cache = getGeocodeCache();
  cache[id] = manual ? { lat, lon, manual: true } : (approx ? { lat, lon, approx: true } : { lat, lon });
  try {
    localStorage.setItem(GEOCODE_CACHE_KEY, JSON.stringify(cache));
  } catch (e) {
    // Cache é apenas uma otimização; se não puder salvar, segue sem ele.
  }
}

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Caixa em volta de Boa Vista: resultado fora dela, para endereço de Boa Vista,
// é erro do serviço de mapas (homônimo em outra cidade) e é descartado.
const BOA_VISTA_BBOX = { south: 2.70, north: 2.95, west: -60.85, east: -60.55 };

// Primeiro endereço de um texto do diretório. Algumas fichas trazem várias
// unidades separadas por <br> ("Unidade X: Av. ..."); mandar tudo junto para o
// serviço de mapas fazia ele errar o ponto.
function mapaRedeFirstAddress(address) {
  let first = String(address == null ? '' : address).split(/<br\s*\/?>/i)[0].replace(/<[^>]+>/g, ' ');
  const m = first.match(/^[^:]{1,70}:\s*(.+)$/);
  if (m && /[A-Za-zÀ-ÿ]/.test(m[1]) && /(\d|,)/.test(m[1])) first = m[1];
  return first.replace(/\s+/g, ' ').trim();
}

// Variações do endereço, da mais completa à mais simples.
function geocodeQueries(address) {
  let a = mapaRedeFirstAddress(address)
    .replace(/\(.*?\)/g, ' ')
    .replace(/,?\s*(CEP[:\s]*)?\d{5}-?\d{3}/gi, '')
    .replace(/\bn[º°o]\.?\s*(?=\d)/gi, '')
    .replace(/\bs\/n(?:[º°]|o\b)?\.?/gi, '')
    .replace(/\b(Qd|Qda|Lote|Lt|Sala|Bloco|Galpão)\.?\s*[\w-]+/gi, '')
    .replace(/,?\s*(em frente|ao lado|próximo|esquina|anexo)\b.*$/i, '')
    .replace(/\bR\.\s/g, 'Rua ').replace(/\bAv\.\s/g, 'Avenida ').replace(/\bGen\.\s/g, 'General ').replace(/\bMaj\.\s/g, 'Major ')
    .replace(/\s+/g, ' ').replace(/\s*,\s*,/g, ',').replace(/[,\s-]+$/, '').trim();
  const parts = a.split(/\s+-\s+/);
  const street = parts[0].replace(/,\s*$/, '');
  const rest = parts.slice(1).join(', ');
  const city = /-RR\b/i.test(a) ? '' : ', Boa Vista';
  const withNumber = street + (rest ? ', ' + rest : '') + city;
  const noNumber = street.replace(/,?\s*\d+[A-Za-z]?\s*$/, '') + (rest ? ', ' + rest : '') + city;
  const out = [withNumber];
  if (noNumber !== withNumber) out.push(noNumber);
  return out.map(q => q.replace(/-RR\b/gi, ', Roraima').replace(/,\s*,/g, ',') + ', Brasil');
}

async function geocodeAddress(address) {
  const isBV = /Boa Vista/i.test(String(address));
  const qs = geocodeQueries(address);
  for (let i = 0; i < qs.length; i++) {
    if (i > 0) await new Promise(r => setTimeout(r, 1100)); // limite do Nominatim: ~1 pedido por segundo
    let url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=br&q=' + encodeURIComponent(qs[i]);
    if (isBV) url += '&viewbox=' + BOA_VISTA_BBOX.west + ',' + BOA_VISTA_BBOX.north + ',' + BOA_VISTA_BBOX.east + ',' + BOA_VISTA_BBOX.south + '&bounded=1';
    const res = await fetch(url, { headers: { 'Accept': 'application/json' } });
    if (!res.ok) throw new Error('Falha ao consultar o serviço de geocodificação.');
    const data = await res.json();
    if (!data || !data[0]) continue;
    const c = { lat: parseFloat(data[0].lat), lon: parseFloat(data[0].lon) };
    if (!isFinite(c.lat) || !isFinite(c.lon)) continue;
    if (isBV && (c.lat < BOA_VISTA_BBOX.south || c.lat > BOA_VISTA_BBOX.north || c.lon < BOA_VISTA_BBOX.west || c.lon > BOA_VISTA_BBOX.east)) continue;
    // Só a rua (sem o número) é menos precisa: marca para a ficha avisar.
    c.approx = i > 0;
    return c;
  }
  return null;
}

async function ensureGeocodedFor(items, onProgress) {
  const cache = getGeocodeCache();
  const pending = items.filter(i => !cache[i.id] && i.address);
  for (let idx = 0; idx < pending.length; idx++) {
    const item = pending[idx];
    if (onProgress) onProgress(idx + 1, pending.length);
    try {
      const coords = await geocodeAddress(item.address);
      if (coords) setGeocodeCacheEntry(item.id, coords.lat, coords.lon, coords.approx);
    } catch (e) {
      // Ignora falha pontual num endereço e segue para o próximo.
    }
    // Respeita o limite de uso do Nominatim (no máximo ~1 requisição por segundo).
    if (idx < pending.length - 1) await new Promise(r => setTimeout(r, 1100));
  }
}

function setProximityButtonLabel(text) {
  const btn = document.getElementById('proximityBtn');
  if (!btn) return;
  const label = btn.querySelector('.proximity-label');
  if (label) label.textContent = text;
  // Enquanto está "Localizando...", sinaliza ocupado (animação + leitor de tela).
  btn.setAttribute('aria-busy', /^Localizando/.test(text) ? 'true' : 'false');
}

function toggleProximitySort() {
  const btn = document.getElementById('proximityBtn');

  if (proximityState.active) {
    proximityState = { active: false, lat: null, lon: null, loading: false };
    if (btn) {
      btn.setAttribute('aria-pressed', 'false');
      btn.classList.remove('is-active');
    }
    setProximityButtonLabel('Ordenar por proximidade');
    render();
    return;
  }

  if (!navigator.geolocation) {
    argoAviso('Este navegador não permite obter a localização atual.', 'error');
    return;
  }

  if (btn) btn.disabled = true;
  setProximityButtonLabel('Localizando...');

  navigator.geolocation.getCurrentPosition(async (pos) => {
    proximityState = { active: true, lat: pos.coords.latitude, lon: pos.coords.longitude, loading: true };

    const activeChip = document.querySelector('.filter-chip.active');
    const cat = activeChip ? activeChip.dataset.cat : 'all';
    const visible = DATA.filter(i => (cat === 'all' || i.cat.includes(cat)) &&
      !i.cat.includes('cas') && !i.cat.includes('cras'));

    await ensureGeocodedFor(visible, (done, total) => {
      setProximityButtonLabel(`Localizando (${done}/${total})...`);
    });

    proximityState.loading = false;
    if (btn) {
      btn.disabled = false;
      btn.setAttribute('aria-pressed', 'true');
      btn.classList.add('is-active');
    }
    setProximityButtonLabel('Mais próximos primeiro');
    render();
  }, () => {
    if (btn) btn.disabled = false;
    setProximityButtonLabel('Ordenar por proximidade');
    argoAviso('Não foi possível obter sua localização. Verifique se a permissão de localização foi concedida ao navegador.', 'error');
  }, { enableHighAccuracy: true, timeout: 15000, maximumAge: 60000 });
}

function renderDistanceBadge(id) {
  if (!proximityState.active) return '';
  const cache = getGeocodeCache();
  const coords = cache[id];
  if (!coords) return `<span class="distance-badge distance-badge-unknown" title="Não foi possível localizar o endereço cadastrado">${ICONS.map} local não encontrado</span>`;
  const km = haversineKm(proximityState.lat, proximityState.lon, coords.lat, coords.lon);
  const label = km < 1 ? `${Math.round(km * 1000)} m` : `${km.toFixed(1)} km`;
  return `<span class="distance-badge">${ICONS.map} ${label}</span>`;
}

const MAX_ATTACH_BYTES = 3.5 * 1024 * 1024;

/* ===================== Cifragem dos dados sensíveis em repouso =====================
   Tudo aqui embaixo cifra/decifra, de forma síncrona (sem depender de
   Promises), o conteúdo salvo sob as chaves sensíveis (attach_/img_/note_/
   userdata_/nota_geral_encaminhamento) antes de gravar no localStorage e ao
   lê-lo de volta. A chave de cifragem (sessionEncKey) é derivada da senha
   do login — ver bloco de Autenticação, no topo do arquivo. */

function bytesToBase64(bytes) {
  // Em blocos: montar a string byte a byte era muito lento em anexos de MB.
  let bin = '';
  const BLOCK = 0x8000;
  for (let i = 0; i < bytes.length; i += BLOCK) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + BLOCK));
  }
  return btoa(bin);
}

function base64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

// PRNG determinístico e rápido (mulberry32): a partir de uma semente de 32
// bits, gera um fluxo de números pseudoaleatórios sempre igual para a mesma
// semente — é o que transforma "chave + nonce" em um fluxo de bytes de
// cifragem (keystream), de forma totalmente síncrona.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function() {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Mistura um array de bytes numa única semente de 32 bits (hash simples,
// estilo FNV) — usado para combinar a chave da sessão com o nonce de cada
// valor cifrado.
function seedFromBytes(bytes) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < bytes.length; i++) {
    h ^= bytes[i];
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

// Gera "length" bytes pseudoaleatórios a partir da chave da sessão + de um
// nonce aleatório específico deste valor salvo (para que o mesmo texto
// nunca produza o mesmo resultado cifrado duas vezes).
function keystream(length, keyBytes, nonceBytes) {
  const combined = new Uint8Array(keyBytes.length + nonceBytes.length);
  combined.set(keyBytes, 0);
  combined.set(nonceBytes, keyBytes.length);
  // mulberry32 inline. Produz EXATAMENTE os mesmos bytes de antes
  // (Math.floor(rnd() * 256) == os 8 bits mais altos de cada saída de 32
  // bits), então os dados já salvos continuam decifrando normalmente — só
  // que sem uma chamada de função + divisão de ponto flutuante por byte.
  let a = seedFromBytes(combined) >>> 0;
  const out = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    out[i] = (t ^ (t >>> 14)) >>> 24;
  }
  return out;
}

function xorBytes(a, b) {
  const out = new Uint8Array(a.length);
  for (let i = 0; i < a.length; i++) out[i] = a[i] ^ b[i % b.length];
  return out;
}

/* ---- Cifra forte (modo senha forte): ChaCha20-Poly1305, RFC 8439 ----------
   Síncrona (o app precisa ler os dados durante a renderização, e WebCrypto
   é assíncrono), com chave de 256 bits vinda do PBKDF2 e nonce aleatório de
   96 bits por valor. Poly1305 autentica: chave errada ou dado adulterado é
   DETECTADO (devolve null) em vez de virar lixo. Conferida byte a byte
   contra a implementação do Node/OpenSSL. Formato: "enc2:<nonce>:<cifrado+tag>". */
/* ChaCha20-Poly1305 (RFC 8439), síncrono, em JS puro. */
function argoChaChaBlock(key32, counter, nonce12) {
  const s = new Uint32Array(16);
  s[0] = 0x61707865; s[1] = 0x3320646e; s[2] = 0x79622d32; s[3] = 0x6b206574;
  const kv = new DataView(key32.buffer, key32.byteOffset, 32);
  for (let i = 0; i < 8; i++) s[4 + i] = kv.getUint32(i * 4, true);
  s[12] = counter >>> 0;
  const nv = new DataView(nonce12.buffer, nonce12.byteOffset, 12);
  s[13] = nv.getUint32(0, true); s[14] = nv.getUint32(4, true); s[15] = nv.getUint32(8, true);
  const x = new Uint32Array(s);
  const qr = (a, b, c, d) => {
    x[a] = (x[a] + x[b]) >>> 0; x[d] ^= x[a]; x[d] = (x[d] << 16) | (x[d] >>> 16);
    x[c] = (x[c] + x[d]) >>> 0; x[b] ^= x[c]; x[b] = (x[b] << 12) | (x[b] >>> 20);
    x[a] = (x[a] + x[b]) >>> 0; x[d] ^= x[a]; x[d] = (x[d] << 8) | (x[d] >>> 24);
    x[c] = (x[c] + x[d]) >>> 0; x[b] ^= x[c]; x[b] = (x[b] << 7) | (x[b] >>> 25);
  };
  for (let r = 0; r < 10; r++) {
    qr(0, 4, 8, 12); qr(1, 5, 9, 13); qr(2, 6, 10, 14); qr(3, 7, 11, 15);
    qr(0, 5, 10, 15); qr(1, 6, 11, 12); qr(2, 7, 8, 13); qr(3, 4, 9, 14);
  }
  const out = new Uint8Array(64), ov = new DataView(out.buffer);
  for (let i = 0; i < 16; i++) ov.setUint32(i * 4, (x[i] + s[i]) >>> 0, true);
  return out;
}
function argoChaChaXor(key32, counter, nonce12, data) {
  const out = new Uint8Array(data.length);
  for (let off = 0; off < data.length; off += 64, counter++) {
    const ks = argoChaChaBlock(key32, counter, nonce12);
    const n = Math.min(64, data.length - off);
    for (let i = 0; i < n; i++) out[off + i] = data[off + i] ^ ks[i];
  }
  return out;
}
function argoPoly1305(key32, msg) {
  const le = (b, o, n) => { let v = 0n; for (let i = n - 1; i >= 0; i--) v = (v << 8n) | BigInt(b[o + i]); return v; };
  const P = (1n << 130n) - 5n;
  const clamp = 0x0ffffffc0ffffffc0ffffffc0fffffffn;
  const r = le(key32, 0, 16) & clamp, sKey = le(key32, 16, 16);
  let acc = 0n;
  for (let off = 0; off < msg.length; off += 16) {
    const n = Math.min(16, msg.length - off);
    const blk = le(msg, off, n) | (1n << BigInt(8 * n));
    acc = ((acc + blk) * r) % P;
  }
  let tag = (acc + sKey) & ((1n << 128n) - 1n);
  const out = new Uint8Array(16);
  for (let i = 0; i < 16; i++) { out[i] = Number(tag & 0xffn); tag >>= 8n; }
  return out;
}
function argoAeadMacData(ct) {
  const pad = (16 - (ct.length % 16)) % 16;
  const m = new Uint8Array(ct.length + pad + 16);
  m.set(ct, 0);
  const dv = new DataView(m.buffer);
  dv.setUint32(ct.length + pad + 8, ct.length >>> 0, true); // aad=0 | len(ct) 64-bit LE
  dv.setUint32(ct.length + pad + 12, Math.floor(ct.length / 4294967296), true);
  return m;
}
function argoAeadSeal(key32, nonce12, plain) {
  const polyKey = argoChaChaBlock(key32, 0, nonce12).subarray(0, 32);
  const ct = argoChaChaXor(key32, 1, nonce12, plain);
  const tag = argoPoly1305(polyKey, argoAeadMacData(ct));
  const out = new Uint8Array(ct.length + 16);
  out.set(ct, 0); out.set(tag, ct.length);
  return out;
}
function argoAeadOpen(key32, nonce12, sealed) {
  if (sealed.length < 16) return null;
  const ct = sealed.subarray(0, sealed.length - 16), tag = sealed.subarray(sealed.length - 16);
  const polyKey = argoChaChaBlock(key32, 0, nonce12).subarray(0, 32);
  const exp = argoPoly1305(polyKey, argoAeadMacData(ct));
  let diff = 0; for (let i = 0; i < 16; i++) diff |= exp[i] ^ tag[i];
  if (diff !== 0) return null;
  return argoChaChaXor(key32, 1, nonce12, ct);
}

// Cifra um texto para guardar no localStorage. Formato salvo:
// "enc1:<nonce em base64>:<texto cifrado em base64>".
function encryptForStorage(plainText) {
  if (!sessionEncKey) {
    console.warn('Argo SUAS: tentativa de salvar dado sensível sem chave de sessão (app trancado?). Dado NÃO foi cifrado.');
    return plainText;
  }
  const plainBytes = new TextEncoder().encode(plainText == null ? '' : String(plainText));
  if (STRONG_AUTH) {
    const nonce12 = crypto.getRandomValues(new Uint8Array(12));
    return 'enc2:' + bytesToBase64(nonce12) + ':' + bytesToBase64(argoAeadSeal(sessionEncKey, nonce12, plainBytes));
  }
  // Formato antigo (enc1): FRACO — semente de só 32 bits. Só é gravado enquanto
  // a senha forte não estiver ativada em auth-config.js.
  const nonce = crypto.getRandomValues(new Uint8Array(16));
  const cipherBytes = xorBytes(plainBytes, keystream(plainBytes.length, sessionEncKey, nonce));
  return 'enc1:' + bytesToBase64(nonce) + ':' + bytesToBase64(cipherBytes);
}

// Decifra um valor lido do localStorage. Valores antigos, salvos antes desta
// cifragem existir (ou sem o prefixo "enc1:"), são devolvidos como estão —
// isso permite migrar dados antigos automaticamente: eles continuam sendo
// lidos normalmente e passam a ser salvos já cifrados na próxima edição.
function decryptFromStorage(stored) {
  if (typeof stored !== 'string') return stored;
  if (stored.startsWith('enc2:')) {
    if (!STRONG_AUTH || !sessionEncKey) return ''; // trancado (ou formato novo sem senha forte ativa)
    const p2 = stored.split(':');
    if (p2.length !== 3) return '';
    try {
      const plain = argoAeadOpen(sessionEncKey, base64ToBytes(p2[1]), base64ToBytes(p2[2]));
      return plain ? new TextDecoder().decode(plain) : ''; // null = chave errada ou dado adulterado
    } catch (e) {
      return '';
    }
  }
  if (!stored.startsWith('enc1:')) return stored;
  // enc1 (formato antigo): no modo forte a chave dele é a "legada" (SHA-256 da
  // senha), e a leitura é estrita — lixo (senha trocada) vira '' e não texto torto.
  const key = STRONG_AUTH ? sessionLegacyKey : sessionEncKey;
  if (!key) return ''; // trancado: sem a senha, não dá para decifrar
  const parts = stored.split(':');
  if (parts.length !== 3) return '';
  try {
    const nonce = base64ToBytes(parts[1]);
    const cipherBytes = base64ToBytes(parts[2]);
    const plainBytes = xorBytes(cipherBytes, keystream(cipherBytes.length, key, nonce));
    return new TextDecoder('utf-8', { fatal: STRONG_AUTH }).decode(plainBytes);
  } catch (e) {
    return '';
  }
}

// Migração automática (modo forte): no login, regrava como enc2 tudo o que
// ainda está em enc1. É "tudo ou nada": primeiro decifra e confere todos os
// valores na memória; se QUALQUER um não decifrar direito (ex.: a senha foi
// trocada e os dados são da senha antiga), não altera nada — assim nunca
// destrói dado por engano. Se uma gravação falhar no meio, o que sobrou
// continua legível como enc1 (ver decryptFromStorage).
function migrateLegacyEncryption() {
  const result = { migrated: 0, failed: 0, aborted: false };
  if (!STRONG_AUTH || !sessionEncKey || !sessionLegacyKey) return result;
  try {
    const items = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !isSensitiveDataKey(k)) continue;
      const v = localStorage.getItem(k);
      if (typeof v === 'string' && v.startsWith('enc1:')) items.push([k, v]);
    }
    if (!items.length) return result;
    const plains = [];
    for (const [k, v] of items) {
      const parts = v.split(':');
      const p = decryptFromStorage(v);
      if (p === '' && !(parts.length === 3 && parts[2] === '')) {
        result.aborted = true;
        result.failed = items.length;
        console.warn('Argo SUAS: dados antigos não decifraram com esta senha; migração cancelada sem alterar nada.');
        return result;
      }
      plains.push([k, p]);
    }
    for (const [k, p] of plains) {
      try { localStorage.setItem(k, encryptForStorage(p)); result.migrated++; }
      catch (e) { result.failed++; }
    }
  } catch (e) { console.warn('Argo SUAS: falha na migração da cifra', e); }
  return result;
}

// Anexos (fotos/PDFs de até 3,5 MB) eram lidos e DECIFRADOS de novo, um por
// um, a cada render() — ou seja, a cada tecla digitada na busca. Agora ficam
// na memória (só enquanto o app está destrancado; lockApp/unlockApp limpam)
// e são descartados sempre que safeStorage.set/remove mexe na chave deles.
const _attachCache = new Map();
function invalidateAttachCache(key) {
  if (typeof key !== 'string') return;
  if (key.startsWith('attach_')) _attachCache.delete(key.slice(7));
  else if (key.startsWith('img_')) _attachCache.delete(key.slice(4));
}

const safeStorage = {
  get(key, fallback = null) {
    try {
      const v = localStorage.getItem(key);
      if (v === null) return fallback;
      return isSensitiveDataKey(key) ? decryptFromStorage(v) : v;
    } catch (e) {
      return fallback;
    }
  },
  getJSON(key, fallback) {
    try {
      const raw = localStorage.getItem(key);
      if (raw === null) return fallback;
      const text = isSensitiveDataKey(key) ? decryptFromStorage(raw) : raw;
      if (!text) return fallback;
      return JSON.parse(text);
    } catch (e) {
      return fallback;
    }
  },
  set(key, value) {
    try {
      const toStore = isSensitiveDataKey(key) ? encryptForStorage(value) : value;
      localStorage.setItem(key, toStore);
      invalidateAttachCache(key);
      return true;
    } catch (e) {
      return false;
    }
  },
  remove(key) {
    try {
      localStorage.removeItem(key);
      invalidateAttachCache(key);
      return true;
    } catch (e) {
      return false;
    }
  }
};

// --- Tema claro/escuro ---
// Sem preferência salva, o app segue o tema do sistema operacional
// (nenhum atributo data-theme é aplicado, e o CSS reage via
// prefers-color-scheme). Ao usar o botão de alternância, a escolha
// fica salva e passa a valer mesmo que o sistema mude de tema depois.
const THEME_KEY = 'argo_theme_pref';

function systemPrefersDark() {
  return !!(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
}

function getEffectiveTheme() {
  const stored = safeStorage.get(THEME_KEY, null);
  if (stored === 'light' || stored === 'dark') return stored;
  return systemPrefersDark() ? 'dark' : 'light';
}

function updateThemeToggleUI() {
  const btn = document.getElementById('themeToggleBtn');
  if (!btn) return;
  const effective = getEffectiveTheme();
  const sunIcon = btn.querySelector('.icon-sun');
  const moonIcon = btn.querySelector('.icon-moon');
  if (sunIcon) sunIcon.hidden = effective === 'dark';
  if (moonIcon) moonIcon.hidden = effective !== 'dark';
  btn.setAttribute('aria-pressed', effective === 'dark' ? 'true' : 'false');
  btn.title = effective === 'dark' ? 'Mudar para modo claro' : 'Mudar para modo escuro';
}

function applyStoredTheme() {
  const stored = safeStorage.get(THEME_KEY, null);
  if (stored === 'light' || stored === 'dark') {
    document.documentElement.setAttribute('data-theme', stored);
  } else {
    document.documentElement.removeAttribute('data-theme');
  }
  updateThemeToggleUI();
}

function setTheme(mode) {
  if (mode !== 'light' && mode !== 'dark') return;
  safeStorage.set(THEME_KEY, mode);
  applyStoredTheme();
}

function toggleTheme() {
  setTheme(getEffectiveTheme() === 'dark' ? 'light' : 'dark');
}

const BF_HIGHLIGHT_HTML = `
  <div style="margin-top:0.75rem; padding:0.75rem; border-left:3px solid var(--brand-primary); background:rgba(17,94,89,0.06); border-radius:6px; font-size:0.8rem;">
    <strong style="color:var(--brand-primary);">Condicionalidades do Bolsa Família:</strong>
    Frequência escolar: crianças e adolescentes entre 6 e 18 anos incompletos devem ter, no mínimo, 75% de presença nas aulas.
    Educação infantil: para crianças de 4 a 6 anos, a exigência mínima de frequência é de 60%.
  </div>
`;

function stripHtml(html) {
  return String(html).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '');
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatInformeDesc(desc) {
  let html = String(desc);

  // Rótulos mais específicos (com emoji, quando é assim que aparecem no
  // texto de origem) vêm ANTES dos genéricos correspondentes na lista
  // abaixo, para que fiquem destacados por inteiro (emoji incluso). A
  // ordem, porém, deixou de ser garantia de segurança contra negrito
  // duplicado — ver o guard "(?<!<strong>)" logo abaixo, que evita
  // envolver em <strong> um rótulo que já esteja dentro de um <strong>
  // (seja porque o texto de origem já veio em negrito, seja porque um
  // rótulo mais longo da lista já envolveu esse mesmo trecho antes).
  const labels = [
    '⚠️ Observações técnicas:',
    'Atividades por idade:',
    '📝 Como acessar:',
    '📝 Como solicitar:',
    '📝 Onde emitir em Boa Vista:',
    'Como acessar:',
    'Como solicitar:',
    'Como usar:',
    'Como funciona:',
    'Requisitos:',
    'Atividades:',
    'Benefícios:',
    'Canais para solicitação:',
    'Documentos necessários:',
    'Duas formas de solicitação:',
    'Gerar ID Jovem e mais informações:',
    'Link para solicitação:',
    'Quantidade de recargas:',
    'Site:'
  ];
  // IMPORTANTE: os rótulos são casados numa ÚNICA passada (um só regex
  // combinado), não num laço com um replace por rótulo. Antes, um laço
  // por rótulo tinha um bug real: depois que a passada já tinha
  // negritado, por ex., "📝 Como acessar:" para "<strong>📝 Como
  // acessar:</strong>", a passada seguinte do rótulo genérico "Como
  // acessar:" ainda CASAVA de novo dentro desse trecho — porque os 8
  // caracteres imediatamente antes de "Como" eram "📝 " (emoji + espaço),
  // não literalmente "<strong>", então o guard "(?<!<strong>)" não
  // pegava esse caso e deixava passar. O resultado era um <strong>
  // aninhado e desbalanceado (ex.: "<strong>📝 <strong>Como
  // acessar:</strong></strong>"), que quebrava a divisão em seções da
  // Guia impressa (splitInformeGuideSections, que corta o texto em
  // "<br>" seguido de "<strong>") — sobrava um "</strong>" solto numa
  // seção e um "<strong>" sem fechar na anterior. Isso já estava
  // acontecendo de verdade nas fichas de Gás do Povo, Carteira do Idoso,
  // Acessuas Trabalho e Primeira Infância no SUAS/Criança Feliz (todas
  // usam "📝 Como acessar:" ou "📝 Como solicitar:").
  //
  // Com um único regex combinado (alternação), cada trecho do texto só
  // pode ser consumido por UM match — o replace global nunca reexamina
  // caracteres que um match anterior já consumiu. Ordenando os rótulos
  // do mais longo para o mais curto, a alternação sempre prefere casar
  // "📝 Como acessar:" (a versão com emoji) inteira antes de considerar
  // a versão curta "Como acessar:" — então a versão curta nunca chega a
  // casar dentro do que a versão longa já engoliu. O guard "(?<!<strong>)"
  // continua aqui, agora só para o outro caso: um rótulo já escrito à
  // mão em negrito no próprio cadastro (ex.: <strong>Requisitos:</strong>).
  const sortedLabels = labels.slice().sort((a, b) => b.length - a.length);
  const escapedAlternatives = sortedLabels.map(l => l.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  const combinedRe = new RegExp('(?<!<strong>)(?:' + escapedAlternatives.join('|') + ')', 'g');
  html = html.replace(combinedRe, match => '<br><strong>' + match + '</strong>');

  html = html.replace(/\s*•\s*/g, '<br>• ');

  html = html.replace(/(\d+\))\s+/g, '<br>$1 ');

  html = html.replace(/(https?:\/\/[^\s<]+)/g, function(match) {
    const trailingMatch = match.match(/[).,;:!?\]]+$/);
    let url = match;
    let suffix = '';
    if (trailingMatch) {
      suffix = trailingMatch[0];
      url = match.slice(0, match.length - suffix.length);
    }
    return '<a href="' + url + '" target="_blank" rel="noopener noreferrer">' + url + '</a>' + suffix;
  });

  html = html.replace(/^(<br>)+/, '').replace(/(<br>){2,}/g, '<br>');

  return html;
}

// Reaproveita formatInformeDesc (mesma fonte usada no card "O que é" da
// aba Programas, Projetos e Serviços) e separa o HTML já formatado em três
// blocos, para montar a Guia impressa desses itens com "O que é",
// "Como Participar" e "Documentação Necessária" bem distintos, em vez do
// bloco único mostrado no card. A separação é feita nos mesmos pontos
// "<br><strong>Rótulo:</strong>" já produzidos por formatInformeDesc (tanto
// os rótulos que ela mesma coloca em negrito quanto os que já vêm em
// negrito no próprio texto de origem, ex.: "Como solicitar:").
function splitInformeGuideSections(descRaw) {
  const formatted = formatInformeDesc(descRaw);
  const parts = formatted.split(/<br>(?=<strong>)/);
  const intro = parts[0] || '';

  const HOW_TO_LABELS = ['requisitos', 'canais para solicitação', 'duas formas de solicitação', 'como solicitar', 'como acessar', 'como usar', 'como funciona', 'onde emitir', 'link para solicitação', 'gerar id jovem', 'quantidade de recargas', 'site'];
  const DOC_LABELS = ['documentos necessários'];

  const howTo = [];
  const docs = [];
  const extra = [];

  for (let k = 1; k < parts.length; k++) {
    const block = parts[k];
    const m = /^<strong>([^<]+)<\/strong>/.exec(block);
    const label = m ? m[1].toLowerCase().replace(/:\s*$/, '').trim() : '';
    if (DOC_LABELS.some(l => label.includes(l))) {
      docs.push(block);
    } else if (HOW_TO_LABELS.some(l => label.includes(l))) {
      howTo.push(block);
    } else {
      extra.push(block);
    }
  }

  return {
    description: [intro, ...extra].filter(Boolean).join('<br>').replace(/^(<br>)+/, ''),
    howTo: howTo.join('<br>'),
    docs: docs.join('<br>')
  };
}

function informeMetaRow(icon, label, value) {
  const raw = value || '';
  let clean = stripHtml(raw).trim();
  if (!clean) return '';

  const naPrefixMatch = raw.match(/^\s*n\/a\s*[-–]\s*([\s\S]+)$/i);
  const display = naPrefixMatch ? naPrefixMatch[1] : raw;

  clean = stripHtml(display).trim();
  if (!clean || clean.toUpperCase() === 'N/A') return '';
  return `<div class="info-group"><span class="info-icon">${icon}</span><div><span class="label-tech">${label}</span>${display}</div></div>`;
}

