// ======= Helpers de data e de nomes =======

// Nome por extenso de uma data marcada. "FAC." vira "Ponto facultativo"; as
// demais siglas vêm de ARGO_AGENDA_LABEL_NAMES (definido no topo do arquivo).
function agendaFullName(info) {
  if (!info) return '';
  return ARGO_AGENDA_LABEL_NAMES[info.label] || String(info.label).replace(/\.$/, '');
}

function agendaDateFromKey(key) {
  const p = key.split('-').map(Number);
  return new Date(p[0], p[1] - 1, p[2]);
}

// Chave AAAA-MM-DD a partir de um Date qualquer (agendaKeyFor sempre usa
// AGENDA_YEAR, então não serve para dias vizinhos na virada do ano).
function agendaIsoKey(date) {
  return date.getFullYear() + '-' + String(date.getMonth() + 1).padStart(2, '0') + '-' + String(date.getDate()).padStart(2, '0');
}

// Título do dia. Ponto facultativo colado num feriado ganha a explicação
// ("antes de Tiradentes", "depois de Corpus Christi"), deduzida das próprias
// datas cadastradas em AGENDA_DATA_INFO — nada é inventado.
function agendaDayTitle(key) {
  const info = AGENDA_DATA_INFO[key];
  if (!info) return '';
  const name = agendaFullName(info);
  if (info.label !== 'FAC.') return name;
  const date = agendaDateFromKey(key);
  const prev = new Date(date); prev.setDate(date.getDate() - 1);
  const next = new Date(date); next.setDate(date.getDate() + 1);
  const nInfo = AGENDA_DATA_INFO[agendaIsoKey(next)];
  const pInfo = AGENDA_DATA_INFO[agendaIsoKey(prev)];
  if (nInfo && argoAgendaKind(nInfo) === 'feriado') return name + ' (antes de ' + agendaFullName(nInfo) + ')';
  if (pInfo && argoAgendaKind(pInfo) === 'feriado') return name + ' (depois de ' + agendaFullName(pInfo) + ')';
  return name;
}

function agendaLongDate(date) {
  return date.toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' });
}

// "hoje", "amanhã", "em 10 dias", "há 3 dias" — só para datas até 60 dias de
// distância; além disso o rótulo seria ruído.
function agendaRelativeLabel(key) {
  const now = new Date();
  const t0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const days = Math.round((agendaDateFromKey(key) - t0) / 86400000);
  if (days === 0) return 'hoje';
  if (days === 1) return 'amanhã';
  if (days === -1) return 'ontem';
  if (days > 1 && days <= 60) return 'em ' + days + ' dias';
  if (days < -1 && days >= -60) return 'há ' + (-days) + ' dias';
  return '';
}

function agendaJoinPt(parts) {
  if (parts.length <= 1) return parts[0] || '';
  return parts.slice(0, -1).join(', ') + ' e ' + parts[parts.length - 1];
}

// ======= Anotações do dia (várias por dia, nunca sobrescrevem as antigas) =======

// Lê o documento do Firestore de um dia e devolve sempre uma lista de
// entradas [{text, createdAt}], da mais antiga para a mais nova. Entende
// tanto o formato novo ({entries: [...]}) quanto o formato antigo de uma
// nota só por dia ({text, updatedAt}), usado antes desta versão — assim,
// anotações já sincronizadas por outros aparelhos não somem.
function agendaEntriesFromDocData(data) {
  if (!data) return [];
  // Textos novos chegam cifrados ("enc1:...", ver agendaCommitEntries); textos
  // antigos em claro passam direto por decryptFromStorage e continuam legíveis.
  if (Array.isArray(data.entries)) {
    return data.entries
      .filter(e => e && e.text)
      .map(e => Object.assign({}, e, { text: decryptFromStorage(e.text) }))
      .filter(e => e.text);
  }
  if (data.text) {
    const ts = (data.updatedAt && typeof data.updatedAt.toMillis === 'function') ? data.updatedAt.toMillis() : null;
    const t = decryptFromStorage(data.text);
    return t ? [{ text: t, createdAt: ts }] : [];
  }
  return [];
}

// Texto curto para os lugares com espaço só para uma linha (grade do
// calendário, resumo da semana, notificação): uma anotação aparece inteira;
// várias viram "3 anotações — mais recente: ...". A lista completa, com
// hora de cada uma, só aparece dentro do próprio dia (agendaRenderEntriesList).
function agendaEntriesPreview(entries) {
  // Anotações marcadas como feitas saem dos resumos (grade, semana, notificação);
  // continuam na lista do dia e na busca.
  const open = (entries || []).filter(e => e && !e.done);
  if (!open.length) return '';
  if (open.length === 1) return agendaEntryShort(open[0]);
  // Com horários, a primeira do dia (a mais cedo) é a que importa; sem
  // horários, a ordem é a de escrita e vale a mais recente, como antes.
  const ordered = agendaDisplayOrder(open).map(i => open[i]);
  const hasTime = ordered.some(e => agendaCleanTime(e.time));
  return open.length + ' anotações — ' + (hasTime ? 'primeira: ' + agendaEntryShort(ordered[0]) : 'mais recente: ' + open[open.length - 1].text);
}

// Texto da anotação com o horário na frente, quando ela tem um ("09:30 Visita").
function agendaEntryShort(e) {
  return (e && e.time ? e.time + ' ' : '') + (e ? e.text : '');
}
// Categorias de anotação (#visita, #grupo...): cor própria no calendário e nas listas.
// Guardada em entry.cat (chave simples, sem texto sensível).
const AGENDA_CATS = {
  atendimento: { label: 'Atendimento', color: '#1b7fa8' },
  visita:      { label: 'Visita',      color: '#c9730f' },
  grupo:       { label: 'Grupo',       color: '#7a4fb5' },
  reuniao:     { label: 'Reunião',     color: '#2f8a6b' },
  prazo:       { label: 'Prazo',       color: '#c13b3b' }
};
function agendaCleanCat(c) { return (typeof c === 'string' && Object.prototype.hasOwnProperty.call(AGENDA_CATS, c)) ? c : ''; }
// Aceita "#vis", "#reuniao", "#reunião"... (prefixo, sem acento). Devolve a chave ou ''.
function agendaCatFromTag(tag) {
  const t = String(tag || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (t.length < 2) return '';
  return Object.keys(AGENDA_CATS).find(k => k.startsWith(t)) || '';
}
function agendaCatBadge(c) {
  c = agendaCleanCat(c);
  return c ? '<span class="agenda-cat-tag" style="--cat:' + AGENDA_CATS[c].color + '">' + AGENDA_CATS[c].label + '</span>' : '';
}
// Horário válido "HH:MM" (ou '' se vazio/inválido): vem de <input type="time">
// e de outros aparelhos, então não se confia no formato.
function agendaCleanTime(t) {
  return (typeof t === 'string' && /^([01]\d|2[0-3]):[0-5]\d$/.test(t)) ? t : '';
}
// Ordem de exibição de um dia: com horário primeiro (do mais cedo ao mais
// tarde), depois as sem horário na ordem em que foram escritas. Devolve os
// índices ORIGINAIS, que é o que editar/apagar/concluir usam.
function agendaDisplayOrder(entries) {
  return (entries || []).map((e, i) => i).sort((a, b) => {
    const ta = agendaCleanTime(entries[a].time), tb = agendaCleanTime(entries[b].time);
    if (ta && tb) return ta < tb ? -1 : (ta > tb ? 1 : a - b);
    if (ta) return -1;
    if (tb) return 1;
    return a - b;
  });
}

// Filtro do painel "Neste mês": só os dias com anotação pendente.
let agendaOnlyPending = false;
function agendaTogglePending() {
  agendaOnlyPending = !agendaOnlyPending;
  const b = document.getElementById('agendaPendingBtn');
  if (b) b.setAttribute('aria-pressed', agendaOnlyPending ? 'true' : 'false');
  agendaRenderMonthList();
}

function agendaEntryTimeLabel(createdAt) {
  if (!createdAt) return '';
  const d = new Date(createdAt);
  if (isNaN(d.getTime())) return '';
  return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
}

// ======= Avisos rápidos (substituem os alert() da agenda) =======

// Aviso com o mascote Argo (argo-mascot.js). Se o script não carregar,
// cai para o alert() nativo para o usuário nunca ficar sem a mensagem.
// type: 'info' | 'error' | 'notfound' | 'success'
function argoAviso(msg, type, extra) {
  if (typeof ArgoMascot !== 'undefined') {
    const opts = Object.assign({ type: type || 'info' }, extra || {});
    if (!opts.duration && String(msg).length > 90) opts.duration = 9000;
    ArgoMascot.notify(msg, opts);
  } else {
    alert(msg);
  }
}

// ======= Assistente conversacional (mascote Argo) =======
// Painel de conversa montado por argo-mascot.js (ArgoMascot.mountAssistant),
// com o mascote "quase como um assistente" dentro do app: um botão
// flutuante que qualquer um pode abrir a qualquer momento, não só a
// notificação única do login (argoShowGreeting, acima). As respostas são
// uma base fixa de dúvidas frequentes sobre o próprio Argo SUAS — tudo
// roda neste aparelho, nada do que a pessoa digita aqui sai do navegador
// nem é enviado a lugar nenhum (sem IA externa, sem servidor).
// Reaproveita argoNorm() (mesma normalização de acento/maiúscula da busca
// principal) para casar palavras-chave sem se importar com digitação.

function argoAssistantGoTo(cat) {
  const chip = document.querySelector('.filter-chip[data-cat="' + cat + '"]');
  if (chip) chip.click();
}

function argoAssistantFocusSearch() {
  argoAssistantGoTo('all');
  requestAnimationFrame(() => {
    const el = document.getElementById('mainSearch');
    if (el && !el.disabled) el.focus();
  });
}

