// ---------- montagem e eventos
function initAcomp() {
  const root = document.getElementById('acMain');
  if (!root) return;
  acompLoad();
  const $ = id => document.getElementById(id);
  let wb = null;
  const TXT = sheetNorm;

  const colsHtml = () => ACOMP.cols.map((c, i) =>
    '<div class="ac-colrow"><input class="tools-input" data-cl="' + i + '" value="' + sheetEsc(c.l) + '" aria-label="Nome da coluna ' + (i + 1) + '">'
    + '<select class="tools-input" data-cr="' + i + '" aria-label="Função da coluna ' + sheetEsc(c.l) + '">'
    + ACOMP_ROLES.map(r => '<option value="' + r[0] + '"' + (r[0] === c.r ? ' selected' : '') + '>' + r[1] + '</option>').join('') + '</select>'
    + '<button type="button" class="tools-ico-btn" data-cdel="' + i + '" aria-label="Remover a coluna ' + sheetEsc(c.l) + '" title="Remover coluna">✕</button></div>').join('');

  const maskVal = (role, v) => (ACOMP.mask && (role === 'nis' || role === 'cpf') && v ? sheetMask(v) : v);

  const cellHtml = (row, c, i, info) => {
    const v = row.v[i] == null ? '' : String(row.v[i]);
    const bad = info.cell[i], role = c.r;
    const a = ' data-ac="1" data-r="' + row.id + '" data-c="' + i + '" aria-label="' + sheetEsc(c.l) + '"' + (bad ? ' class="ac-in is-bad" title="' + sheetEsc(bad) + '"' : ' class="ac-in"');
    if (ACOMP_DATE_ROLES.indexOf(role) > -1) {
      const p = acompParseDate(v);
      return p || !v ? '<input type="date"' + a + ' value="' + p + '">' : '<input type="text"' + a + ' value="' + sheetEsc(v) + '" placeholder="dd/mm/aaaa">';
    }
    if (role === 'sit') return '<input type="text" list="acSitList"' + a + ' value="' + sheetEsc(v) + '">';
    if (role === 'pessoas' || role === 'num') return '<input type="text" inputmode="numeric"' + a + ' value="' + sheetEsc(v) + '">';
    if (role === 'renda') return '<input type="text" inputmode="decimal"' + a + ' value="' + sheetEsc(v) + '" placeholder="0,00">';
    if (role === 'tel') return '<input type="tel"' + a + ' value="' + sheetEsc(v) + '">';
    if (role === 'nis' || role === 'cpf') return '<input type="text" inputmode="numeric"' + a + ' value="' + sheetEsc(maskVal(role, v)) + '" data-secret="' + (ACOMP.mask && v ? '1' : '') + '" autocomplete="off">';
    return '<input type="text"' + a + ' value="' + sheetEsc(v) + '">';
  };

  const computedHtml = (info, ix) => {
    let h = '';
    if (ix.proximo !== undefined) { const p = acompPrazoTxt(info); h += '<td class="ac-prazo ac-p-' + p[1] + '">' + p[0] + '</td>'; }
    if (ix.pessoas !== undefined && ix.renda !== undefined) h += '<td class="ac-pc ' + acompPcCls(info.pc) + '">' + (info.pc == null ? '—' : pcMoney(info.pc)) + '</td>';
    return h;
  };

  const filtered = S => {
    const ix = acompIdx(), v = ACOMP.view, q = TXT(v.q).split(/\s+/).filter(Boolean);
    const out = ACOMP.rows.filter(r => {
      const i = S.infos.get(r.id);
      if (v.f === 'venc' && !(i.st === 'venc' && !i.closed)) return false;
      if (v.f === 'prox' && !((i.st === 'hoje' || i.st === 'sem') && !i.closed)) return false;
      if (v.f === 'semret' && !(i.st === 'none' && !i.closed && ix.proximo !== undefined)) return false;
      if (v.f === 'semat' && !(i.semAt && !i.closed)) return false;
      if (v.f === 'dup' && !(ix.nis !== undefined && ACOMP.dup.get(sheetDupKey(r.v[ix.nis])) > 1)) return false;
      if (v.f === 'prob' && !i.flags.length) return false;
      if (v.sit && String(r.v[ix.sit] || '').trim() !== v.sit) return false;
      if (v.bairro && String(r.v[ix.bairro] || '').trim() !== v.bairro) return false;
      if (v.tec && String(r.v[ix.tecnico] || '').trim() !== v.tec) return false;
      if (q.length) { const hay = TXT(r.v.join(' ')); if (!q.every(t => hay.indexOf(t) > -1)) return false; }
      return true;
    });
    if (v.sort !== null) {
      const k = v.sort, d = v.dir;
      const key = r => {
        const i = S.infos.get(r.id);
        if (k === '#pc') return i.pc == null ? null : i.pc;
        if (k === '#prazo') return i.prox || null;
        const role = ACOMP.cols[k].r, val = String(r.v[k] == null ? '' : r.v[k]).trim();
        if (!val) return null;
        if (ACOMP_DATE_ROLES.indexOf(role) > -1) return acompParseDate(val) || null;
        if (role === 'pessoas' || role === 'num') return toolsNum(val);
        if (role === 'renda') return pcParse(val);
        return TXT(val);
      };
      out.sort((a, b) => {
        const x = key(a), y = key(b);
        if (x === null && y === null) return 0;
        if (x === null) return 1; if (y === null) return -1; // vazios sempre no fim
        return (x < y ? -1 : x > y ? 1 : 0) * d;
      });
    }
    return out;
  };

  const paintStats = S => {
    const ix = acompIdx(), f = ACOMP.view.f;
    const chip = (k, label, n, cls) => '<button type="button" class="tools-chip ac-chip ' + (cls || '') + (f === k ? ' is-active' : '') + '" data-f="' + k + '" aria-pressed="' + (f === k ? 'true' : 'false') + '">' + label + ' <b>' + n + '</b></button>';
    let h = chip('all', 'Todas', S.total);
    if (ix.proximo !== undefined) h += chip('venc', 'Vencidos', S.venc, S.venc ? 'ac-c-venc' : '') + chip('prox', 'Hoje e 7 dias', S.hoje + S.sem7, S.hoje ? 'ac-c-hoje' : '') + chip('semret', 'Sem retorno marcado', S.semRet);
    if (ix.ultimo !== undefined) h += chip('semat', 'Sem atendimento +' + ACOMP.gap + ' d', S.semAt);
    if (ix.nis !== undefined) h += chip('dup', 'NIS repetido', S.dup, S.dup ? 'ac-c-venc' : '');
    h += chip('prob', 'Com problema', S.prob, S.prob ? 'ac-c-hoje' : '');
    $('acStats').innerHTML = h;
    let sum = '';
    if (S.pcN) {
      const L = acompPcLimits();
      sum = 'Renda per capita média: <b>' + pcMoney(S.pcSoma / S.pcN) + '</b> (' + S.pcN + ' famílias com renda e nº de pessoas) · até ' + pcMoney(L.bf) + ': <b>' + S.bf + '</b> · até ½ salário mínimo (' + pcMoney(L.sm / 2) + '): <b>' + S.meio + '</b>';
    }
    if (S.sit.size > 1) sum += (sum ? '<br>' : '') + [...S.sit.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8).map(e => sheetEsc(e[0]) + ': <b>' + e[1] + '</b>').join(' · ');
    $('acSummary').innerHTML = sum;
    $('acSummary').hidden = !sum;
  };

  const fillSel = (id, wid, role, cur) => {
    const ix = acompIdx(), w = $(wid), sel = $(id);
    if (ix[role] === undefined) { w.hidden = true; return; }
    const set = new Set();
    ACOMP.rows.forEach(r => { const t = String(r.v[ix[role]] || '').trim(); if (t) set.add(t); });
    const arr = [...set].sort((a, b) => a.localeCompare(b, 'pt-BR'));
    sel.innerHTML = '<option value="">Todos</option>' + arr.map(t => '<option value="' + sheetEsc(t) + '"' + (t === cur ? ' selected' : '') + '>' + sheetEsc(t) + '</option>').join('');
    w.hidden = arr.length < 2;
  };

  const renderTable = S => {
    const ix = acompIdx(), v = ACOMP.view, list = filtered(S);
    const pages = Math.max(1, Math.ceil(list.length / ACOMP_PAGE));
    if (v.page >= pages) v.page = pages - 1;
    if (v.page < 0) v.page = 0;
    const slice = list.slice(v.page * ACOMP_PAGE, (v.page + 1) * ACOMP_PAGE);
    const th = (label, key, cls) => '<th scope="col" class="' + (cls || '') + '"><button type="button" class="ac-sort" data-sort="' + key + '" aria-label="Ordenar por ' + sheetEsc(label) + '">' + sheetEsc(label)
      + (String(v.sort) === String(key) ? '<span aria-hidden="true">' + (v.dir === 1 ? ' ▲' : ' ▼') + '</span>' : '') + '</button></th>';
    // Prazo e renda per capita ficam logo depois do nome, para aparecerem sem rolar a tabela para o lado.
    const compHead = (ix.proximo !== undefined ? th('Prazo', '#prazo', 'ac-c-prazo') : '')
      + (ix.pessoas !== undefined && ix.renda !== undefined ? th('Per capita', '#pc', 'ac-c-pc') : '');
    let head = '<tr><th scope="col" class="ac-n">#</th>' + (ix.nome === undefined ? compHead : '');
    ACOMP.cols.forEach((c, k) => { head += th(c.l, k, 'ac-c-' + c.r) + (k === ix.nome ? compHead : ''); });
    head += '<th scope="col" class="ac-c-act">Ações</th></tr>';
    const body = slice.map(r => {
      const i = S.infos.get(r.id), n = ACOMP.rows.indexOf(r) + 1;
      return '<tr data-row="' + r.id + '" class="' + (i.closed ? 'is-closed ' : '') + (i.st === 'venc' && !i.closed ? 'is-venc' : '') + '"><td class="ac-n">' + n + '</td>'
        + (ix.nome === undefined ? computedHtml(i, ix) : '')
        + ACOMP.cols.map((c, k) => '<td class="ac-c-' + c.r + '">' + cellHtml(r, c, k, i) + '</td>' + (k === ix.nome ? computedHtml(i, ix) : '')).join('')
        + '<td class="ac-act"><button type="button" class="ac-btn" data-act="today" title="Registrar atendimento hoje e marcar o próximo retorno">✓ Hoje</button>'
        + '<button type="button" class="ac-btn" data-act="note" title="Abrir ou criar a nota desta família" aria-label="Nota desta família">📝</button>'
        + '<button type="button" class="ac-btn" data-act="calc" title="Calcular a renda per capita no cartão Renda per capita" aria-label="Calcular renda per capita">🧮</button>'
        + '<button type="button" class="ac-btn ac-del" data-act="del" title="Remover esta família (dá para desfazer)" aria-label="Remover esta família">✕</button></td></tr>';
    }).join('');
    $('acTable').innerHTML = '<thead>' + head + '</thead><tbody>' + (body || '<tr><td class="ac-none" colspan="' + (ACOMP.cols.length + 4) + '">Nenhuma família neste filtro.</td></tr>') + '</tbody>';
    $('acPager').innerHTML = list.length
      ? '<button type="button" class="tools-link-btn" data-pg="-1"' + (v.page ? '' : ' disabled') + '>‹ Anterior</button><span>' + (list.length === S.total ? S.total + ' famílias' : list.length + ' de ' + S.total) + ' · página ' + (v.page + 1) + ' de ' + pages + '</span><button type="button" class="tools-link-btn" data-pg="1"' + (v.page < pages - 1 ? '' : ' disabled') + '>Próxima ›</button>'
      : '';
  };

  const renderAll = () => {
    acompLoad();
    const has = ACOMP.rows.length > 0 || ACOMP.cols.length > 0;
    $('acMain').hidden = !has; $('acEmpty').hidden = has;
    $('acTemplate').hidden = has;
    $('acKeep').checked = ACOMP.keep; $('acMask').checked = ACOMP.mask;
    $('acInterv').value = ACOMP.intervalo; $('acGap').value = ACOMP.gap;
    if (has) {
      const S = acompSummary();
      const ix = acompIdx(), sits = new Set(ACOMP_SIT);
      if (ix.sit !== undefined) ACOMP.rows.forEach(r => { const t = String(r.v[ix.sit] || '').trim(); if (t) sits.add(t); });
      $('acSitList').innerHTML = [...sits].map(t => '<option value="' + sheetEsc(t) + '">').join('');
      fillSel('acSit', 'acSitW', 'sit', ACOMP.view.sit); fillSel('acBairro', 'acBairroW', 'bairro', ACOMP.view.bairro); fillSel('acTec', 'acTecW', 'tecnico', ACOMP.view.tec);
      $('acSearch').value = ACOMP.view.q;
      paintStats(S); renderTable(S);
      $('acCols').innerHTML = colsHtml();
    }
    acompPaintPend();
  };

  // atualiza só a linha editada (não tira o foco de quem está digitando)
  const afterEdit = (row, tr) => {
    const S = acompSummary(), ix = acompIdx(), info = S.infos.get(row.id);
    if (tr) {
      tr.classList.toggle('is-closed', info.closed);
      tr.classList.toggle('is-venc', info.st === 'venc' && !info.closed);
      tr.querySelectorAll('input[data-ac]').forEach(inp => {
        const bad = info.cell[inp.dataset.c];
        inp.classList.toggle('is-bad', !!bad);
        if (bad) inp.title = bad; else inp.removeAttribute('title');
      });
      const pz = tr.querySelector('.ac-prazo');
      if (pz) { const p = acompPrazoTxt(info); pz.textContent = p[0]; pz.className = 'ac-prazo ac-p-' + p[1]; }
      const pc = tr.querySelector('.ac-pc');
      if (pc) { pc.textContent = info.pc == null ? '—' : pcMoney(info.pc); pc.className = 'ac-pc ' + acompPcCls(info.pc); }
    }
    paintStats(S);
    acompPaintPend(); acompSave();
  };

  // ---- arquivo
  const readAoa = ws => {
    const X = window.XLSX;
    // raw:true devolve números e datas de verdade (raw:false traria "1,500.00" no formato americano e quebraria a renda)
    const aoa = X.utils.sheet_to_json(ws, { header: 1, raw: true, defval: '', blankrows: true });
    return aoa.map(r => r.map(v => (v instanceof Date ? acompPad(v.getDate()) + '/' + acompPad(v.getMonth() + 1) + '/' + v.getFullYear() : String(v == null ? '' : v))));
  };
  const doImport = aoa => {
    const hadRows = ACOMP.rows.length;
    if (hadRows && !confirm('Substituir a planilha atual (' + hadRows + ' famílias) pela planilha importada?\n\nDepois de importar, dá para desfazer por 15 segundos.')) return;
    const n = acompImportMatrix(aoa);
    if (!n) { acompSay('Não encontrei linhas de dados nessa planilha. A primeira linha precisa ser o cabeçalho.'); return; }
    renderAll(); acompSave();
    acompSay(n + ' famílias importadas. Confira em “Colunas e funções” se cada coluna ficou com a função certa.' + (n > 3000 ? ' Planilha grande: se não salvar neste aparelho, baixe o .xlsx.' : ''));
  };
  $('acFile').addEventListener('change', async () => {
    const f = $('acFile').files && $('acFile').files[0]; if (!f) return;
    if (f.size > SHEET_MAX_BYTES) { acompSay('O arquivo passa de 25 MB. Divida a planilha em partes menores.'); $('acFile').value = ''; return; }
    acompSay('Lendo a planilha…');
    try {
      const buf = await f.arrayBuffer(), ext = (f.name.split('.').pop() || '').toLowerCase();
      if (ext === 'xlsx' || ext === 'xls') {
        if (!window.XLSX) await pdftoolsLoadScript(SHEET_XLSX_URL);
        wb = window.XLSX.read(buf, { type: 'array', cellDates: true, dateNF: 'dd/mm/yyyy' });
        $('acSheet').innerHTML = wb.SheetNames.map((n, i) => '<option value="' + i + '">' + sheetEsc(n) + '</option>').join('');
        $('acSheetRow').hidden = wb.SheetNames.length < 2;
        doImport(readAoa(wb.Sheets[wb.SheetNames[0]]));
      } else {
        wb = null; $('acSheetRow').hidden = true;
        let text; try { text = new TextDecoder('utf-8', { fatal: true }).decode(buf); } catch (e) { text = new TextDecoder('windows-1252').decode(buf); }
        doImport(sheetParseCsv(text));
      }
    } catch (e) {
      acompSay(/Falha ao carregar/.test(String(e && e.message)) ? 'Para abrir .xlsx ou .xls pela primeira vez é preciso internet. Sem internet, salve a planilha como CSV e importe de novo.'
        : 'Não consegui ler esse arquivo. Confira se é .csv, .xlsx ou .xls e se não está protegido por senha.');
    }
    $('acFile').value = '';
  });
  $('acSheet').addEventListener('change', () => { if (wb) doImport(readAoa(wb.Sheets[wb.SheetNames[parseInt($('acSheet').value, 10) || 0]])); });
  $('acTemplate').addEventListener('click', () => { acompStartTemplate(); renderAll(); acompSave(); const f = root.querySelector('input[data-ac]'); if (f) f.focus(); });

  // ---- desfazer
  $('acUndo').addEventListener('click', () => {
    if (!ACOMP.undo) return;
    const fn = ACOMP.undo; ACOMP.undo = null; clearTimeout(ACOMP.undoT);
    $('acUndo').hidden = true; fn(); renderAll(); acompSave(); acompSay('Desfeito.');
  });

  // ---- edição de célula
  root.addEventListener('focusin', e => {
    const inp = e.target.closest && e.target.closest('input[data-secret="1"]'); if (!inp) return;
    const row = acompRow(inp.dataset.r); if (row) inp.value = row.v[+inp.dataset.c] || '';
  });
  root.addEventListener('focusout', e => {
    const inp = e.target.closest && e.target.closest('input[data-ac]'); if (!inp) return;
    const c = ACOMP.cols[+inp.dataset.c]; if (!c || (c.r !== 'nis' && c.r !== 'cpf')) return;
    const row = acompRow(inp.dataset.r); if (!row) return;
    inp.dataset.secret = ACOMP.mask && row.v[+inp.dataset.c] ? '1' : '';
    inp.value = maskVal(c.r, row.v[+inp.dataset.c] || '');
  });
  root.addEventListener('change', e => {
    const inp = e.target.closest && e.target.closest('input[data-ac]'); if (!inp) return;
    const row = acompRow(inp.dataset.r), i = +inp.dataset.c, c = ACOMP.cols[i]; if (!row || !c) return;
    let val = inp.value.trim();
    if (ACOMP_DATE_ROLES.indexOf(c.r) > -1) {
      if (inp.type === 'text') { const p = acompParseDate(val); if (p) { val = p; inp.type = 'date'; inp.value = p; inp.placeholder = ''; } }
    } else if (c.r === 'pessoas') { val = val.replace(/\D/g, '').slice(0, 3); inp.value = val; }
    row.v[i] = val;
    afterEdit(row, inp.closest('tr'));
  });

  // ---- cliques: filtros, ordenação, páginas, ações da linha
  root.addEventListener('click', e => {
    const ch = e.target.closest('[data-f]');
    if (ch) { ACOMP.view.f = ch.dataset.f; ACOMP.view.page = 0; renderAll(); return; }
    const so = e.target.closest('[data-sort]');
    if (so) {
      const k = so.dataset.sort[0] === '#' ? so.dataset.sort : +so.dataset.sort;
      if (String(ACOMP.view.sort) === String(k)) { if (ACOMP.view.dir === 1) ACOMP.view.dir = -1; else { ACOMP.view.sort = null; ACOMP.view.dir = 1; } }
      else { ACOMP.view.sort = k; ACOMP.view.dir = 1; }
      ACOMP.view.page = 0; renderAll(); return;
    }
    const pg = e.target.closest('[data-pg]');
    if (pg) { ACOMP.view.page += +pg.dataset.pg; renderAll(); $('acTable').scrollIntoView({ block: 'nearest' }); return; }
    const b = e.target.closest('[data-act]'); if (!b) return;
    const tr = b.closest('tr'), row = tr && acompRow(tr.dataset.row); if (!row) return;
    const ix = acompIdx();
    if (b.dataset.act === 'today') {
      if (ix.ultimo === undefined && ix.proximo === undefined) { acompSay('Defina as funções “Último atendimento” e “Retorno previsto” em “Colunas e funções”.'); return; }
      const prev = row.v.slice(), t = acompToday();
      if (ix.ultimo !== undefined) row.v[ix.ultimo] = t;
      if (ix.proximo !== undefined) row.v[ix.proximo] = acompAddDays(t, ACOMP.intervalo);
      acompUndoSet('Atendimento registrado em ' + acompBr(t) + (ix.proximo !== undefined ? '; retorno marcado para ' + acompBr(acompAddDays(t, ACOMP.intervalo)) : '') + '.', () => { row.v = prev; }, 'Desfazer');
      renderAll(); acompSave();
    } else if (b.dataset.act === 'del') {
      const at = ACOMP.rows.indexOf(row), code = acompCode(row, ix);
      ACOMP.rows.splice(at, 1);
      acompUndoSet('Família removida (' + code + ').', () => { ACOMP.rows.splice(Math.min(at, ACOMP.rows.length), 0, row); }, 'Desfazer remoção');
      renderAll(); acompSave();
    } else if (b.dataset.act === 'calc') acompToRenda(row);
    else if (b.dataset.act === 'note') acompToNote(row);
  });

  let qT = null;
  $('acSearch').addEventListener('input', e => { clearTimeout(qT); const val = e.target.value; qT = setTimeout(() => { ACOMP.view.q = val; ACOMP.view.page = 0; const S = acompSummary(); renderTable(S); }, 150); });
  [['acSit', 'sit'], ['acBairro', 'bairro'], ['acTec', 'tec']].forEach(([id, k]) => $(id).addEventListener('change', e => { ACOMP.view[k] = e.target.value; ACOMP.view.page = 0; renderTable(acompSummary()); }));

  // ---- botões da barra
  $('acAdd').addEventListener('click', () => {
    ACOMP.view = Object.assign(ACOMP.view, { q: '', f: 'all', sit: '', bairro: '', tec: '', sort: null, dir: 1 });
    ACOMP.rows.push({ id: acompRid(), v: acompBlank() });
    ACOMP.view.page = Math.floor((ACOMP.rows.length - 1) / ACOMP_PAGE);
    renderAll(); acompSave();
    const inputs = root.querySelectorAll('tbody tr:last-child input[data-ac]'); if (inputs[0]) inputs[0].focus();
  });
  $('acPend').addEventListener('click', () => {
    const t = acompPendText();
    if (!t) { acompSay(acompPendSummary() ? 'Nenhum retorno vencido, de hoje ou dos próximos 7 dias.' : 'Defina a coluna “Retorno previsto” em “Colunas e funções” para listar pendências.'); return; }
    toolsCopyText(t, 'Pendências copiadas.');
  });
  $('acXlsx').addEventListener('click', acompDownloadXlsx);
  $('acCsv').addEventListener('click', acompDownloadCsv);
  $('acClear').addEventListener('click', () => {
    if (!ACOMP.rows.length && !ACOMP.cols.length) return;
    const before = { cols: ACOMP.cols, rows: ACOMP.rows };
    ACOMP.cols = []; ACOMP.rows = []; ACOMP.view = { q: '', f: 'all', sit: '', bairro: '', tec: '', sort: null, dir: 1, page: 0 };
    acompSaveNow();
    acompUndoSet('Planilha limpa' + (ACOMP.keep ? ' (e apagada deste aparelho)' : '') + '.', () => { ACOMP.cols = before.cols; ACOMP.rows = before.rows; }, 'Desfazer limpeza');
    renderAll();
  });
  $('acKeep').addEventListener('change', e => {
    ACOMP.keep = e.target.checked; acompPrefSave();
    if (ACOMP.keep) { acompSay(acompSaveNow() ? 'Planilha guardada neste aparelho, cifrada. Ela volta sozinha na próxima vez.' : 'Não consegui guardar neste aparelho (armazenamento cheio ou bloqueado).'); }
    else { safeStorage.remove(ACOMP_KEY); acompSay('Cópia guardada neste aparelho apagada. A planilha continua na tela até você fechar o app.'); }
  });
  $('acMask').addEventListener('change', e => { ACOMP.mask = e.target.checked; acompPrefSave(); renderAll(); });
  $('acInterv').addEventListener('change', e => { const n = parseInt(e.target.value, 10); ACOMP.intervalo = n > 0 ? Math.min(365, n) : 30; e.target.value = ACOMP.intervalo; acompPrefSave(); });
  $('acGap').addEventListener('change', e => { const n = parseInt(e.target.value, 10); ACOMP.gap = n > 0 ? Math.min(730, n) : 30; e.target.value = ACOMP.gap; acompPrefSave(); renderAll(); });

  // ---- colunas e funções
  const cols = $('acCols');
  cols.addEventListener('change', e => {
    const l = e.target.closest('[data-cl]'), r = e.target.closest('[data-cr]');
    if (l) { ACOMP.cols[+l.dataset.cl].l = l.value.trim() || 'Coluna ' + (+l.dataset.cl + 1); }
    else if (r) {
      const i = +r.dataset.cr, role = r.value;
      if (role !== 'txt' && role !== 'data' && role !== 'num') ACOMP.cols.forEach((c, k) => { if (k !== i && c.r === role) c.r = 'txt'; }); // um papel de cada
      ACOMP.cols[i].r = role;
      ACOMP.rows.forEach(row => { row.v[i] = acompNormalize(role, row.v[i]); });
    } else return;
    renderAll(); acompSave();
  });
  cols.addEventListener('click', e => {
    const d = e.target.closest('[data-cdel]'); if (!d) return;
    const i = +d.dataset.cdel, c = ACOMP.cols[i];
    const used = ACOMP.rows.some(r => String(r.v[i] || '').trim());
    if (used && !confirm('Remover a coluna “' + c.l + '” e os dados dela?\n\nDepois dá para desfazer por 15 segundos.')) return;
    const snap = { cols: ACOMP.cols.map(x => Object.assign({}, x)), vals: ACOMP.rows.map(r => r.v.slice()) };
    ACOMP.cols.splice(i, 1); ACOMP.rows.forEach(r => r.v.splice(i, 1));
    acompUndoSet('Coluna “' + c.l + '” removida.', () => { ACOMP.cols = snap.cols; ACOMP.rows.forEach((r, k) => { r.v = snap.vals[k] || snap.cols.map(() => ''); }); }, 'Desfazer remoção');
    renderAll(); acompSave();
  });
  $('acColAdd').addEventListener('click', () => {
    ACOMP.cols.push({ l: 'Nova coluna', r: 'txt' }); ACOMP.rows.forEach(r => r.v.push(''));
    renderAll(); acompSave();
    const inp = cols.querySelector('[data-cl="' + (ACOMP.cols.length - 1) + '"]'); if (inp) { inp.focus(); inp.select(); }
  });

  // botão "Ver na planilha" do Relógio
  const pend = $('toolsPend');
  if (pend) pend.querySelector('button').addEventListener('click', () => {
    ACOMP.view.f = 'prox'; ACOMP.view.page = 0;
    const p = acompPendSummary(); if (p && p.venc) ACOMP.view.f = 'venc';
    renderAll(); acompGoCard('acomp');
  });
  ACOMP.render = renderAll;
  renderAll();
}


/* ============================================================
   IA NO MASCOTE ARGO (cérebro em js/argo-cerebro.js)
   Ordem de resposta, da mais segura para a mais flexível:
     1) pedido de socorro / risco de vida → telefones de emergência, na hora;
     2) pergunta sobre unidade (telefone, endereço, horário, bairro) →
        fichas reais do diretório, mesmo sem internet;
     3) dúvida conceitual do SUAS → base offline com a norma de referência;
     4) pedidos de navegação do app (abas, ferramentas) → respostas prontas;
     5) o que sobrou → IA em streaming pelo Paulus (se houver internet e ARGO_IA.url),
        com o histórico da conversa e até 10 fichas do diretório; o Paulus
        acrescenta trechos de norma com citação e, se a IA falhar, usa a base
        de normas offline;
     6) se a IA falhar, vale a resposta pronta.
   Sai do aparelho (só no passo 5): a pergunta e o histórico filtrados, até 10 fichas públicas
   do diretório e, quando pertinente, trechos agregados do Censo SUAS 2025. Perguntas com documento,
   telefone, e-mail, nome e sobrenome ou endereço residencial são barradas
   antes de qualquer envio. Nada de famílias, planilhas ou bloco de notas.
   A conversa fica só na memória da página e é apagada ao trancar o app.
   ============================================================ */
const ARGO_IA = {
  // Worker do Paulus (repositório "paulus", wrangler.toml name = "paulus-ia"); vazio = IA desligada.
  // O Paulus responde com citação de norma e é o mesmo cérebro dos outros apps (Anona, Toth, Umbrella).
  url: 'https://paulus-ia.paulo-ae18.workers.dev'
};

let argoBrainReady = false;
let argoCensoReady = Promise.resolve(0);
function argoBrain() {
  if (typeof ArgoCerebro === 'undefined') return null;
  if (!argoBrainReady) {
    ArgoCerebro.init({ data: typeof DATA !== 'undefined' ? DATA : [], ia: { url: ARGO_IA.url }, refs: typeof PC_REF !== 'undefined' ? PC_REF : {} });
    // Paulus (js/paulus.v1.js): faz a ida à IA e traz a base de normas offline (assets/conhecimento.json).
    // Se o arquivo não carregar, o app segue com o transporte antigo do ArgoCerebro.
    if (typeof Paulus !== 'undefined' && ARGO_IA.url) {
      Paulus.init({ app: 'argo', endpoint: ARGO_IA.url, conhecimentoUrl: 'assets/conhecimento.json' });
    }
    // Os trechos agregados do Censo SUAS 2025 vêm do mesmo pacote leve usado pela busca offline do Paulus.
    // O Argo seleciona apenas os trechos pertinentes a perguntas sobre psicólogos/equipes e os envia como baseApp.
    if (typeof fetch === 'function' && typeof ArgoCerebro.setCensoSuas === 'function') {
      argoCensoReady = fetch('assets/conhecimento.json', { credentials: 'omit' })
        .then(r => r.ok ? r.json() : null)
        .then(j => ArgoCerebro.setCensoSuas(Array.isArray(j) ? j : []))
        .catch(() => 0);
    }
    // Tabela da CID-11 (Capítulo 06): carrega do aparelho/cache (sw.js a guarda para uso offline). Sem isso o cérebro
    // responde "a tabela da CID-11 ainda não carregou" para qualquer código ou nome de transtorno.
    if (typeof fetch === 'function' && typeof ArgoCerebro.setCid === 'function') {
      fetch('assets/cid11.json', { credentials: 'omit' })
        .then(r => (r.ok ? r.json() : null))
        .then(j => { if (j) ArgoCerebro.setCid(j); })
        .catch(() => { /* sem tabela: o cérebro avisa que ela não carregou */ });
    }
    // Municípios de Roraima (população, indígenas, área, CadÚnico/PBF/BPC): gerado por scripts/gerar-municipios-rr.mjs.
    // Sem o arquivo o mascote só não responde esses números direto (a IA e o diretório seguem como antes).
    if (typeof fetch === 'function' && typeof ArgoCerebro.setMunicipios === 'function') {
      fetch('assets/municipios-rr.json', { credentials: 'omit' })
        .then(r => (r.ok ? r.json() : null))
        .then(j => { if (j) ArgoCerebro.setMunicipios(j); })
        .catch(() => { /* sem a base de municípios */ });
    }
    argoBrainReady = true;
  }
  return ArgoCerebro;
}

function argoAssistantStatus() {
  const B = argoBrain();
  if (navigator.onLine === false) return { text: 'Sem internet · respostas prontas', level: 'off' };
  if (B && B.aiOn()) return { text: 'IA ativa · diretório e base SUAS offline', level: 'ok' };
  return { text: 'Respostas prontas (sem IA)', level: 'warn' };
}

function argoActiveTabInfo() {
  const active = document.querySelector('#filterBar .filter-chip.active');
  const cat = active ? active.dataset.cat : 'all';
  const nm = active ? ((active.querySelector('span:not(.chip-icon):not(.chip-count)') || {}).textContent || '').trim() : '';
  return { cat: cat === 'all' ? '' : cat, name: nm };
}

function argoAssistantOpenUnit(u) {
  if (!u) return;
  argoAssistantSearch(u.name || '');
  if (argoAssistantCtrl && argoAssistantCtrl.close) argoAssistantCtrl.close();
}

// Converte o resultado do cérebro (declarativo) no formato da interface do mascote.
function argoAssistantToUi(result, rawText, allowAiChip) {
  const B = argoBrain();
  const out = Object.assign({}, result);
  out.quickActions = (result.quickActions || []).map(a => {
    if (a.run) return a;
    if (a.cat) return { label: a.label, run: () => argoAssistantGoTo(a.cat), reply: 'Abri "' + a.label.replace(/^(Ver|Abrir)\s+/i, '') + '".', mood: 'success' };
    if (a.search !== undefined) return { label: a.label, run: () => (a.search ? argoAssistantSearch(a.search) : argoAssistantFocusSearch()), reply: a.search ? 'Pronto! Joguei essa busca no diretório.' : 'Pronto! O cursor já está na busca.', mood: 'success' };
    return a;
  });
  if (allowAiChip && B && B.aiOn() && !result.crisis) out.quickActions.push({ label: '✨ Aprofundar com a IA', ask: rawText, force: true });
  out.units = argoUnitsForUi(result.units);
  return out;
}
function argoUnitsForUi(units) {
  const B = argoBrain();
  return (units || []).map(u => Object.assign({}, u, {
    phoneLinks: (u.phones || []).map(p => ({ label: String(p).replace(/\s*\(.*$/, '').trim() || String(p), href: B ? B.telHref(p) : '' })).filter(x => x.href)
  }));
}

// Ponto de entrada do mascote: primeiro a IA INTERPRETA a pergunta (lê a conversa, completa o que ficou
// subentendido, corrige a digitação e a põe na forma que o app sabe consultar com dados reais); depois as
// consultas locais e a resposta seguem como sempre, já com a pergunta bem entendida. Fica de fora, direto
// no fluxo local: socorro, dado pessoal, agenda, "abrir aba", frases muito curtas, "Aprofundar com a IA",
// "tentar de novo" e a resposta ao "de qual bairro?". Sem IA, sem internet ou se a interpretação falhar
// ou demorar, o fluxo local roda com a pergunta original (nunca fica pior do que antes).
// Mensagem longa (mais de 300 caracteres, ex.: um caso descrito em termos gerais) já é autônoma: não é reescrita,
// senão a interpretação a encurtaria para ~200 caracteres e a IA perderia os detalhes.
function argoAssistantAskHybrid(rawText, meta) {
  const B = argoBrain();
  meta = meta || {};
  const texto = String(rawText == null ? '' : rawText).trim();
  // Se o mascote acabou de pedir um esclarecimento, a resposta curta ("Caimbé") precisa passar pela interpretação,
  // que a junta à pergunta anterior; por isso o limite de tamanho mínimo não vale nesse turno.
  const aguardando = !!(B && B.session && B.session.aguardando);
  if (B && B.session) B.session.aguardando = false;
  const pular = !B || typeof B.interpretar !== 'function' || !B.aiOn() || meta.forceAI || meta.regen || meta.semInterpretar ||
    (texto.length < 4 && !aguardando) || texto.length > 300 || _ubsPsiAguarda || B.crisis(texto) || B.piiBlock(texto) || argoAgendaAsk(texto) || argoThemeAsk(texto) || argoOpenTabAsk(texto) ||
    (typeof B.psi === 'function' && B.psi(texto).score >= 3) ||
    (typeof B.planMulti === 'function' && !!B.planMulti(texto, {}));   // duas partes de contato: o diretório responde as duas, sem a IA reescrever a pergunta
  if (pular) return argoAssistantAskHybridCore(rawText, meta);
  const tab = argoActiveTabInfo();
  return B.interpretar(texto, { tabName: tab.name }).then(i => {
    if (!i) return argoAssistantAskHybridCore(rawText, meta);
    // O que a interpretação descobriu (bairro, unidade, tipo de pedido) fica firmado para os próximos turnos.
    if (typeof B.notar === 'function') B.notar(i);
    // Perguntar de volta é o último recurso: só quando o dado falta de verdade (não está na mensagem, no estado nem na
    // conversa) e o pedido depende dele. Nos demais casos a pergunta segue e a resposta vem com a premissa mais provável.
    if (i.esclarecer && !['ubs_psicologo', 'saudacao', 'agenda', 'navegar', 'fora_do_escopo'].includes(i.intencao) &&
        (typeof B.deveEsclarecer !== 'function' || B.deveEsclarecer(i))) {
      B.remember(texto, i.esclarecer, []);
      B.session.aguardando = true;
      return { reply: i.esclarecer, mood: 'info', badge: 'Entendendo a pergunta', quickActions: [] };
    }
    // Cumprimento, agenda, "abrir tela" e assunto alheio seguem com as palavras da pessoa.
    if (['saudacao', 'agenda', 'navegar', 'fora_do_escopo'].includes(i.intencao)) return argoAssistantAskHybridCore(rawText, meta);
    let q = i.pergunta || texto;
    // UBS com psicólogo: a forma é sempre a mesma, para o local reconhecer o bairro mesmo que a IA mude a frase.
    // O bairro pode vir da própria interpretação ou do que a conversa já firmou.
    if (i.intencao === 'ubs_psicologo') {
      const bairroUbs = i.bairro || (B.estado && B.estado().bairro) || '';
      q = bairroUbs ? 'Qual UBS tem psicólogo no bairro ' + bairroUbs + '?' : 'Qual UBS tem psicólogo para o bairro da pessoa?';
    }
    // Dado pessoal na reescrita: volta para a pergunta original (o Core avisa se for o caso).
    if (B.piiBlock(q) || B.crisis(q)) q = texto;
    return argoAssistantAskHybridCore(q, meta);
  }, () => argoAssistantAskHybridCore(rawText, meta));
}

// Fluxo local + IA de resposta (recebe a pergunta já interpretada).
function argoAssistantAskHybridCore(rawText, meta) {
  const B = argoBrain();
  if (!B) return argoAssistantAsk(rawText);
  meta = meta || {};
  const tab = argoActiveTabInfo();
  const keep = (res, units) => { B.remember(rawText, res.reply, units); return res; };
  const questionLike = /\?|^(como|o que|qual|quais|quando|posso|devo|por que|porque|quem|existe|ha|há)\b/i.test(rawText.trim()) || rawText.trim().split(/\s+/).length >= 6;

  // Dado pessoal na pergunta: avisa na hora (a pergunta só sai do aparelho se for à IA,
  // mas o ideal é nem digitar nomes e documentos aqui). Pedido de socorro tem prioridade.
  if (!B.crisis(rawText)) {
    const aviso = B.piiBlock(rawText);
    if (aviso) return { reply: aviso, mood: 'notfound', quickActions: [] };
  }

  // Perguntas sobre a Agenda são respondidas aqui, com os dados do aparelho: nunca vão à IA
  // nem entram na memória da conversa (podem citar anotações pessoais).
  const agendaAnswer = argoAgendaAsk(rawText);
  if (agendaAnswer) return agendaAnswer;

  // Pedido para trocar o tema ("modo escuro"): troca na hora, sem passar pela IA.
  const themeAnswer = argoThemeAsk(rawText);
  if (themeAnswer) return themeAnswer;
  const closeAnswer = argoCloseAppAsk(rawText);
  if (closeAnswer) return closeAnswer;

  // Pedido claro para abrir uma aba ("abre o mapa"): abre na hora, sem passar pela IA.
  const tabOpen = argoOpenTabAsk(rawText);
  if (tabOpen) return tabOpen;

  // UBS com psicólogo por bairro: responde na hora com os dados do diretório (a IA entra só se a pessoa pedir).
  // Mensagem longa (mais de 300 caracteres: um caso descrito, um pedido de texto) vai à IA com as palavras da pessoa;
  // citar uma unidade ou um bairro no meio dela não pode virar resposta pronta do diretório.
  const longMsg = rawText.trim().length > 300 && B.aiOn();
  const ubsPsi = longMsg ? null : argoUbsPsicoAsk(rawText);
  if (ubsPsi) return keep(ubsPsi, ubsPsi.units);

  // Pergunta com duas partes de contato ("telefone do CRAS e do CREAS"): cada parte é respondida pelo diretório.
  if (!meta.forceAI && !meta.regen && !longMsg && typeof B.planMulti === 'function') {
    const multi = B.planMulti(rawText, { tabCat: tab.cat });
    if (multi) return keep(argoAssistantToUi(multi.result, rawText, false), multi.result.units);
  }
  // "e do Conselho Tutelar?" depois de um pedido de contato: mantém o que se pedia (telefone, endereço, horário).
  if (!meta.forceAI && !meta.regen && !longMsg && typeof B.planSeguimento === 'function') {
    const seg = B.planSeguimento(rawText, { tabCat: tab.cat });
    if (seg) return keep(argoAssistantToUi(seg.result, rawText, false), seg.result.units);
  }

  let plan = { kind: 'none' };
  let local = null;
  if (!meta.forceAI && !meta.regen) {
    plan = B.plan(rawText, { tabCat: tab.cat });
    // Socorro e consulta ao diretório (telefone, endereço, horário, bairro) continuam respondidos na hora, com os dados reais.
    if (plan.kind === 'crisis' || (plan.kind === 'directory' && !longMsg)) {
      return keep(argoAssistantToUi(plan.result, rawText, false), plan.result.units);
    }
    // Dúvida do psicólogo no SUAS: verbete curado, com a norma citada. Responde na hora, mesmo com a IA ligada
    // (a resposta precisa ser a da norma); a IA fica a um toque, em "Aprofundar com a IA".
    // 'ficha': requisitos/documentos/valor copiados do cartão do diretório (mesmo tratamento do psi: responde na hora, IA a um toque)
    if ((plan.kind === 'psi' || plan.kind === 'ficha') && !longMsg) {
      return keep(argoAssistantToUi(plan.result, rawText, true), plan.result.units);
    }
    // Dúvida de conteúdo (pergunta de verdade): com a IA ligada, ela responde com a norma e a conversa; o verbete pronto
    // só entra se a IA falhar ou estiver desligada. Frase curta de navegação ("abrir mapa") não é pergunta e segue como antes.
    if (plan.kind === 'concept' && !(B.aiOn() && questionLike)) {
      return keep(argoAssistantToUi(plan.result, rawText, true), plan.result.units);
    }
    local = argoAssistantAsk(rawText);
    // uma palavra solta ("serviço", "unidade") não deve sequestrar uma pergunta que a IA entende melhor
    const longQ = questionLike && B.aiOn();
    if (!longMsg && local && !local.fallback && (local.score || 0) >= 2 && ((local.score || 0) >= 4 || !longQ)) return keep(local);
  } else {
    local = argoAssistantAsk(rawText);
  }

  // lista aproximada do diretório só serve para pedidos curtos ("preciso de um psicólogo"); em pergunta longa vira ruído
  const weak = (plan.kind === 'directory-weak' && rawText.trim().split(/\s+/).length < 6) ? argoAssistantToUi(plan.result, rawText, false) : null;
  // verbete pronto (conceito) que ficou de reserva caso a IA falhe
  const conceito = plan.kind === 'concept' ? argoAssistantToUi(plan.result, rawText, false) : null;
  const iaOk = B.aiOn();
  if (iaOk && (meta.forceAI || meta.regen || !weak || questionLike)) {
    const ai = argoAskAI(rawText, tab, weak || conceito || local);
    if (ai) return ai;
  }
  if (conceito) return keep(conceito, plan.result.units);
  if (weak) return keep(weak, plan.result.units);
  // Sem IA (offline ou desligada) e sem resposta pronta que sirva: a base de normas do Paulus, que já está no aparelho.
  if (!iaOk && questionLike && (!local || local.fallback || (local.score || 0) < 2)) {
    const norma = argoAskNormasOffline(rawText, local);
    if (norma) return norma;
  }
  if (local) return keep(local);
  return local;
}

// Pergunta de conteúdo sem IA: procura na base de normas do Paulus (assets/conhecimento.json, também em cache offline).
// Volta como resposta em stream só para o mascote esperar a base carregar; se nada na base sustenta a pergunta,
// rejeita e o mascote mostra a resposta de reserva (a mesma que mostraria antes), então o usuário nunca fica pior.
function argoAskNormasOffline(rawText, local) {
  const B = argoBrain();
  if (!B || typeof Paulus === 'undefined' || !Paulus.consultarNormas) return null;
  const reserva = local || { reply: 'Estou sem internet e não achei isso na minha base de normas. Não quero inventar resposta. Posso procurar o termo direto no diretório.', mood: 'notfound', quickActions: [{ label: 'Buscar \"' + rawText.slice(0, 22) + '\" nos equipamentos', run: () => argoAssistantSearch(rawText), reply: 'Pronto! Joguei essa busca no diretório.', mood: 'success' }] };
  return {
    reply: '', mood: 'info', badge: 'Base SUAS',
    quickActions: reserva.quickActions,
    stream: {
      fallback: reserva,
      run: () => Paulus.consultarNormas(rawText, { historico: B.session.history }).then(r => {
        if (!r) { if (local) B.remember(rawText, local.reply, []); throw new Error('sem norma'); }
        const txt = B.cleanAI(r.texto);
        if (!txt) throw new Error('vazia');
        B.remember(rawText, txt, []);
        return { text: txt, note: (r.avisos && r.avisos[0]) || 'Confira o texto oficial vigente.', sources: r.fontes || [] };
      })
    }
  };
}

// Trechos de norma que o Paulus consultou (documento + artigo), sem repetir. Texto honesto:
// são os trechos que a base achou para a pergunta, não garantia de que a IA usou todos.
function argoFontesTexto(fontes) {
  const vistos = new Set();
  const itens = [];
  (Array.isArray(fontes) ? fontes : []).forEach(f => {
    const nome = [f && f.documento, f && f.referencia].filter(Boolean).join(', ');
    if (nome && !vistos.has(nome)) { vistos.add(nome); itens.push(nome); }
  });
  return itens.length ? 'Normas consultadas: ' + itens.slice(0, 3).join('; ') + '.' : '';
}

// Ida à IA pelo Paulus. Mantém o contrato do mascote: resolve { txt, fontes, offline } ou rejeita com
// err.partial (texto que já chegou) e err.userMessage (aviso para mostrar no lugar da resposta).
// A conversa e as fichas continuam sendo as do ArgoCerebro (payload); o Paulus só faz a ida à IA,
// a conferência de dado pessoal/socorro e a base de normas.
// Telas do Argo que a IA pode PROPOR como botão (a IA não abre nada: quem toca é a pessoa).
// id = o que o Paulus envia ao Worker; cat = a aba aberta por argoAssistantGoTo.
const ARGO_ACOES_IA = [
  { id: 'mapa', cat: 'mapa', rotulo: 'Mapa dos Equipamentos', descricao: 'Mapa com a localização das unidades' },
  { id: 'agenda', cat: 'agenda', rotulo: 'Agenda Argo', descricao: 'Agenda e compromissos' },
  { id: 'recentes', cat: 'recentes', rotulo: 'Recentes', descricao: 'Últimas unidades abertas' },
  { id: 'ferramentas', cat: 'ferramentas', rotulo: 'Ferramentas e Anotações', descricao: 'Relógio, cálculos, planilha e bloco de notas' },
  { id: 'cras', cat: 'cras', rotulo: 'Registro de Atendimento (CRAS)', descricao: 'Registro de atendimentos do CRAS' },
  { id: 'cas', cat: 'cas', rotulo: 'Registro de Atendimento (CAS)', descricao: 'Registro de atendimentos do CAS' },
  { id: 'pdftools', cat: 'pdftools', rotulo: 'Central de PDF', descricao: 'Ferramentas para PDF' },
  { id: 'tradutor', cat: 'tradutor', rotulo: 'Tradutor', descricao: 'Tradutor Es/En/Fr' },
  { id: 'noticias', cat: 'noticias', rotulo: 'Notícias', descricao: 'Notícias do MDS, MEC e Saúde' },
  { id: 'raps', cat: 'saude', rotulo: 'Rede RAPS', descricao: 'Rede de Atenção Psicossocial (CAPS, UBS de saúde mental)' },
  { id: 'social', cat: 'social', rotulo: 'Proteção Social (CRAS/CREAS)', descricao: 'Proteção Social Básica e Especial' },
  { id: 'tea', cat: 'tea', rotulo: 'Rede TEA e PCD', descricao: 'Atenção à Pessoa com Deficiência e TEA' },
  { id: 'conselho', cat: 'conselho', rotulo: 'Conselho Tutelar', descricao: 'Proteção à criança e ao adolescente' },
  { id: 'mulher', cat: 'mulher', rotulo: 'Rede de Enfrentamento à Violência contra a Mulher', descricao: 'Serviços de atenção à mulher' },
  { id: 'previdencia', cat: 'previdencia', rotulo: 'Previdência (INSS)', descricao: 'Agências e serviços do INSS' },
  { id: 'documentacao', cat: 'documentacao', rotulo: 'Documentação Civil', descricao: 'Serviços de documentação civil e fiscal' }
];

function argoStreamIA(B, rawText, payload, hooks) {
  if (typeof Paulus === 'undefined' || !Paulus.perguntar) {
    return B.streamAI(payload, hooks).then(txt => {
      const p = B.separarSugestoes ? B.separarSugestoes(txt) : { texto: txt, sugestoes: [] };
      return { txt: p.texto || txt, fontes: [], offline: false, sugestoes: p.sugestoes };
    });
  }
  let acc = '';
  let fontes = [];
  // O caminho do Paulus não passa por B.streamAI, que é quem alimenta o aiGate (intervalo mínimo e limite por minuto).
  B.session.lastAi = Date.now(); B.session.aiTimes.push(B.session.lastAi);
  const falha = (msg, userMessage, noRetry) => {
    const e = new Error(msg);
    e.partial = acc;
    if (userMessage) e.userMessage = userMessage;
    if (noRetry) e.noRetry = true; // dado pessoal e socorro: repetir a mesma pergunta não resolve
    return e;
  };
  return Paulus.perguntar(rawText, {
    aba: payload.pagina,
    semAcoes: true,                 // "abrir/buscar" já foram tratados pelo Argo antes de chegar aqui
    // A IA pode PROPOR estas telas como botões (Paulus v0.4.0); nada abre sozinho.
    acoes: ARGO_ACOES_IA.map(a => ({ id: a.id, rotulo: a.rotulo, descricao: a.descricao, executar: () => argoAssistantGoTo(a.cat) })),
    fichas: payload.contexto,
    baseApp: payload.base,          // verbetes conferidos, valores de referência e calendário PBF do próprio app
    panorama: payload.panorama,     // totais reais do diretório por grupo ("quantos CAPS?"); sem isso a IA contaria fichas soltas
    historico: payload.historico,
    semPerguntar: hooks.semPerguntar === true,   // segunda tentativa: responde com a premissa mais provável
    estado: payload.estado,         // unidade, bairro, município e assunto já firmados na conversa (Paulus v0.8.0)
    sinal: hooks.signal,
    onToken: (pedaco, tudo) => { acc = tudo; if (hooks.onDelta) hooks.onDelta(pedaco, tudo); },
    onFontes: f => { fontes = f; }
  }).then(r => {
    if (hooks.signal && hooks.signal.aborted) throw falha('interrompida');
    if (r.tipo === 'ia') {
      const txt = B.cleanAI(r.texto);
      if (!txt) throw falha('vazia');
      return { txt, fontes: r.fontes && r.fontes.length ? r.fontes : fontes, offline: false, sugestoes: r.sugestoes || [], acoes: r.acoes || [] };
    }
    // IA indisponível: se nada chegou ainda, a base de normas pode ter o trecho certo
    if (r.tipo === 'norma' && !acc) {
      return { txt: B.cleanAI(r.texto), fontes: r.fontes || [], avisos: r.avisos || [], offline: true };
    }
    if (r.tipo === 'erro' || r.tipo === 'bloqueio') throw falha(r.tipo, r.texto, r.tipo === 'bloqueio');
    if (r.tipo === 'crise') {
      const tels = (r.telefones || []).map(t => t.numero + ' ' + t.nome).join(' · ');
      throw falha('crise', r.texto + (tels ? '\n' + tels : ''), true);
    }
    throw falha(r.tipo || 'sem_resposta');
  });
}

function argoAskAI(rawText, tab, fallbackResult) {
  const B = argoBrain();
  const bloqueio = B.piiBlock(rawText);
  if (bloqueio) return { reply: bloqueio, mood: 'notfound', quickActions: [] };
  const gate = B.aiGate();
  if (gate) return { reply: gate, mood: 'info', quickActions: fallbackResult ? fallbackResult.quickActions : [] };
  const payload = B.buildPayload(rawText, { tabCat: tab.cat, tabName: tab.name });
  const ctxNames = payload.contexto.map(f => B.norm(f.nome));
  return {
    reply: '', mood: 'info', badge: 'IA',
    stream: {
      fallback: fallbackResult || { reply: 'Não consegui consultar a IA agora. Posso procurar o termo direto no diretório, se você quiser.', mood: 'notfound', quickActions: [{ label: 'Buscar "' + rawText.slice(0, 22) + '" nos equipamentos', run: () => argoAssistantSearch(rawText), reply: 'Pronto! Joguei essa busca no diretório.', mood: 'success' }] },
      run: (onDelta, signal) => argoCensoReady.then(() => {
        const payload = B.buildPayload(rawText, { tabCat: tab.cat, tabName: tab.name });
        const ctxNames = payload.contexto.map(f => B.norm(f.nome));
        // Resposta que só perguntou, com a conversa já em andamento: pede de novo, uma vez, mandando a IA assumir a premissa
        // mais provável e responder (o texto na tela é trocado pela nova resposta). Se falhar, vale a primeira.
        const sondar = typeof Paulus !== 'undefined' && Paulus.conversa && Paulus.conversa.soPerguntou;
        const comConversa = Object.keys(B.estado()).length > 0 || B.session.history.length >= 2;
        const primeira = argoStreamIA(B, rawText, payload, { onDelta, signal });
        const final = !sondar || !comConversa ? primeira : primeira.then(r => {
          if (r.offline || !Paulus.conversa.soPerguntou(r.txt) || (signal && signal.aborted)) return r;
          return new Promise(ok => setTimeout(ok, 1400))        // o Paulus deixa 1,2 s entre perguntas
            .then(() => argoStreamIA(B, rawText, B.buildPayload(rawText, { tabCat: tab.cat, tabName: tab.name }), { onDelta, signal, semPerguntar: true }))
            .then(r2 => (r2 && r2.txt && !Paulus.conversa.soPerguntou(r2.txt) ? r2 : r), () => r);
        });
        return final.then(({ txt, fontes, avisos, offline, sugestoes, acoes }) => {
          const units = B.mentionedUnits(txt, ctxNames);
          B.remember(rawText, txt, units);
          const bad = B.verifyPhones(txt);
          let note = 'Posso errar: confira os dados com a unidade antes de encaminhar.';
          if (offline) note = (avisos && avisos[0]) || 'Estou sem IA agora, mas achei um trecho na minha base SUAS. Confira a fonte e o ano citados.';
          if (bad) note = '⚠️ Citei um número que não consta no diretório. Confirme com a unidade antes de usar.';
          // Perguntas de continuação: as da IA primeiro; se ela citou unidade e não sugeriu nada, as de contato.
          const seguintes = (sugestoes || []).slice(0, 3);
          if (!seguintes.length && units.length) seguintes.push('Qual o telefone?', 'Qual o horário?');
          return {
            text: txt,
            note,
            bad: !!bad,                 // número que não consta no diretório: o mascote fica preocupado
            badge: offline ? 'Base SUAS' : undefined,
            sources: fontes || [],      // o mascote mostra como lista que abre e fecha
            units: argoUnitsForUi(units),
            followups: seguintes,
            // Sem IA agora e a base de normas respondeu: dá um jeito de tentar de novo com a IA
            quickActions: offline
              ? [{ label: '↻ Tentar com a IA de novo', ask: rawText, force: true }]
              // Telas propostas pela IA: botão "Abrir ..." (o mascote confirma com uma frase curta)
              : ((acoes || []).length ? acoes.map(a => ({ label: 'Abrir ' + a.rotulo, run: a.executar, reply: 'Abri: ' + a.rotulo + '.', mood: 'success' })) : undefined)
          };
        }, err => { if (err && err.partial) B.remember(rawText, err.partial, []); throw err; });
      })
    }
  };
}


/* ======================= Dinâmica da navegação =======================
   1) Ao trocar de aba, o conteúdo desliza de leve para o lado certo
      (frente = próxima aba na ordem do menu; trás = anterior).
   2) No celular, em modo destaque, deslizar o dedo para os lados nas
      abas de lista (CRAS, RAPS, SUAS…) vai para a aba anterior/seguinte.
      Fica desligado em campos de texto, tabelas, mapa, agenda e em
      qualquer área que role na horizontal, para não atrapalhar. */
(function initNavDynamics() {
  const grid = document.getElementById('grid');
  const main = document.getElementById('mainContent');
  if (!grid || !main || typeof navAllChips !== 'function') return;
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
  const SLIDE = ['grid-slide-next', 'grid-slide-prev'];
  const active = document.querySelector('#filterBar .filter-chip.active');
  let lastCat = (active && active.dataset.cat) || 'all';

  function slide(dir) {
    if (reduce.matches) return;
    grid.classList.remove(...SLIDE);
    void grid.offsetWidth; // reinicia a animação se ela já estava rodando
    grid.classList.add(dir > 0 ? SLIDE[0] : SLIDE[1]);
  }
  grid.addEventListener('animationend', e => {
    if (e.target === grid) grid.classList.remove(...SLIDE);
  });

  navAllChips().forEach(chip => chip.addEventListener('click', () => {
    const cat = chip.dataset.cat;
    if (!cat || cat === lastCat) return;
    const order = navAllChips().map(c => c.dataset.cat);
    const dir = order.indexOf(cat) >= order.indexOf(lastCat) ? 1 : -1;
    lastCat = cat;
    slide(dir);
  }));

  /* ---- deslizar para trocar de aba (celular, modo destaque) ---- */
  const SWIPE_BLOCK = 'input, textarea, select, button, a, summary, label, table, pre, canvas, [contenteditable], ' +
    '.leaflet-container, [data-no-swipe], #agendaBook, #agendaCalendarGrid, .pdftools-fileitem, .tab-focus-bar, #notesRoot, .tech-card.is-expanded';
  const LIST_ONLY = ['pdftools', 'tradutor', 'noticias', 'mapa', 'agenda', 'appsext', 'ferramentas', 'anotacoes'];
  let sx = 0, sy = 0, st = 0, tracking = false;

  function scrollsSideways(el) {
    for (let n = el; n && n !== main; n = n.parentElement) {
      if (n.scrollWidth > n.clientWidth + 4) {
        const ox = getComputedStyle(n).overflowX;
        if (ox === 'auto' || ox === 'scroll') return true;
      }
    }
    return false;
  }

  main.addEventListener('touchstart', e => {
    tracking = false;
    if (!isTabFocusOpen() || e.touches.length !== 1) return;
    if (LIST_ONLY.includes(lastCat)) return;
    const t = e.target;
    if (!t.closest || t.closest(SWIPE_BLOCK) || scrollsSideways(t)) return;
    const sel = window.getSelection && window.getSelection();
    if (sel && String(sel).length) return; // há texto selecionado
    tracking = true;
    sx = e.touches[0].clientX; sy = e.touches[0].clientY; st = Date.now();
  }, { passive: true });

  main.addEventListener('touchend', e => {
    if (!tracking) return;
    tracking = false;
    const t = e.changedTouches[0];
    const dx = t.clientX - sx, dy = t.clientY - sy;
    if (Date.now() - st > 600 || Math.abs(dx) < 90 || Math.abs(dy) > Math.abs(dx) * 0.5) return;
    const btn = document.getElementById(dx < 0 ? 'tabFocusNext' : 'tabFocusPrev');
    if (btn) btn.click();
  }, { passive: true });
})();
